// globals.js — IRON SIEGE 엔진 네임스페이스 + 튜닝
(function () {
  const IS = globalThis.IS || (globalThis.IS = {});

  IS.CFG = {
    // 렌더
    quality: 'high',            // low | medium | high | ultra
    dprMax: 1.75,
    shadow: 2048,
    autoQuality: true,
    fov: 78,
    fogDensity: 0.012,
    // post
    bloomThreshold: 0.72,
    bloomStrength: 0.55,
    bloomRadius: 1.6,
    chromatic: 0.0016,
    filmGrain: 0.035,

    // 플레이어
    player: {
      eye: 1.68, crouchEye: 1.02, radius: 0.38,
      walk: 4.6, run: 7.4, sprint: 9.2, crouch: 2.2, air: 0.62,
      accel: 52, decel: 44, jump: 6.4, gravity: -22,
      hp: 100, armorMax: 100,
      stepHeight: 0.42,
    },

    // 전투
    gravity: -22,
    bulletSpeed: { rifle: 900, pistol: 420, smg: 620, shotgun: 380, sniper: 1200, lmg: 800, plasma: 260, rail: 2400 },
    tracerEvery: 3,

    // AI
    ai: {
      sightRange: 92,        // 시야 처리
      fovDeg: 100,           // 시야각
      hearingRange: 34,
      gunshotRange: 76,
      grid: 2.0,             // 내비 그리드
      gridRadius: 48,
      navInterval: 0.12,
      evasionChance: 0.22,
      strafe: true,
      maxActive: 48,
      maxAwakeThink: 24,
    },

    // 웨이브
    wave: { baseKills: 12, step: 4, maxKills: 40, intermission: 8 },

    // fx
    fx: { tracers: 96, sparks: 400, smoke: 160, blood: 220, decals: 160 },
  };

  IS.VERSION = '1.0.0';
  IS.fps = 60;
})();

// raycast.js — 空间哈希 + DDA 射线 + 遮挡视线判定
(function () {
  const IS = globalThis.IS || (globalThis.IS = {});
  const T = globalThis.THREE;

  const CELL = 4.0;
  const CW = 200, CH = 200;   // 世界 [-100,100]
  const OX = -100, OZ = -100;

  const Ray = {
    grid: null,           // 静态格（实心）
    gridW: CW, gridH: CH,
    staticBoxes: [],      // {minX,minZ,maxX,maxZ,top,minY}
    colliders: [],        // 世界 AABB（物理查询）
    _hash: null,          // 敌人空间哈希

    init: function () {
      this.grid = new Uint8Array(CW * CH);
      this.staticBoxes.length = 0;
      this.colliders.length = 0;
      this._hash = new IS.Utils.SpatialHash(CELL);
    },

    // ---------- 静态格 ----------
    gx: function (x) { return Math.floor((x - OX) / CELL); },
    gz: function (z) { return Math.floor((z - OZ) / CELL); },
    set: function (x, z, v) {
      const gx = this.gx(x), gz = this.gz(z);
      if (gx < 0 || gz < 0 || gx >= CW || gz >= CH) return;
      this.grid[gz * CW + gx] = v;
    },
    solid: function (x, z) {
      const gx = this.gx(x), gz = this.gz(z);
      if (gx < 0 || gz < 0 || gx >= CW || gz >= CH) return true;
      return this.grid[gz * CW + gx] === 1;
    },

    // 注册一个 AABB 碰撞体（地图用）
    addBox: function (cx, cy, cz, hx, hy, hz, tag) {
      const box = {
        cx, cy, cz, hx, hy, hz,
        minX: cx - hx, maxX: cx + hx, minZ: cz - hz, maxZ: cz + hz,
        minY: cy - hy, maxY: cy + hy, tag: tag || 'solid',
        mesh: null,
      };
      this.colliders.push(box);
      return box;
    },

    // 把碰撞体覆盖的格子标实心
    rasterize: function () {
      for (let i = 0; i < this.colliders.length; i++) {
        const b = this.colliders[i];
        if (b.hz < 0.5 && b.hy < 0.5) continue; // 薄片不挡子弹路径？仍挡
        const gx0 = Math.max(0, this.gx(b.minX)), gx1 = Math.min(CW - 1, this.gx(b.maxX));
        const gz0 = Math.max(0, this.gz(b.minZ)), gz1 = Math.min(CH - 1, this.gz(b.maxZ));
        for (let gz = gz0; gz <= gz1; gz++) for (let gx = gx0; gx <= gx1; gx++) {
          this.grid[gz * CW + gx] = 1;
        }
      }
    },

    // 地图中心留出安全区（清空出生点）
    clearArea: function (cx, cz, r) {
      const gx0 = Math.max(0, this.gx(cx - r)), gx1 = Math.min(CW - 1, this.gx(cx + r));
      const gz0 = Math.max(0, this.gz(cz - r)), gz1 = Math.min(CH - 1, this.gz(cz + r));
      for (let gz = gz0; gz <= gz1; gz++) for (let gx = gx0; gx <= gx1; gx++) {
        this.grid[gz * CW + gx] = 0;
      }
    },

    // ---------- 玩家 AABB 碰撞（圆 vs AABB） ----------
    // 返回修正后的 pos（推出穿透），并写 hit 信息
    resolve: function (pos, radius, height, out) {
      const r = radius, y = pos.y, feet = y, head = y + height;
      let hit = false;
      const near = this._queryBox(pos.x, pos.z, r + 1.2);
      for (let i = 0; i < near.length; i++) {
        const b = near[i];
        if (head < b.minY || feet > b.maxY) continue;
        const nx = Math.max(b.minX, Math.min(pos.x, b.maxX));
        const nz = Math.max(b.minZ, Math.min(pos.z, b.maxZ));
        let dx = pos.x - nx, dz = pos.z - nz;
        let d2 = dx * dx + dz * dz;
        if (d2 > r * r) continue;
        hit = true;
        let d = Math.sqrt(d2);
        if (d < 1e-4) {
          // 中心在盒内：沿最浅轴推出
          const px = Math.min(pos.x - b.minX, b.maxX - pos.x);
          const pz = Math.min(pos.z - b.minZ, b.maxZ - pos.z);
          if (px < pz) pos.x += (pos.x - (b.minX + b.maxX) * 0.5 > 0 ? px + r : -(px + r));
          else pos.z += (pos.z - (b.minZ + b.maxZ) * 0.5 > 0 ? pz + r : -(pz + r));
          continue;
        }
        const push = (r - d);
        pos.x += (dx / d) * push;
        pos.z += (dz / d) * push;
        if (out) { out.box = b; out.hit = true; }
      }
      if (out && !hit) out.hit = false;
      return hit;
    },

    _nearBuf: [],
    _queryBox: function (x, z, r) {
      const out = this._nearBuf; out.length = 0;
      // 优先网格粗筛（仅静态：用格索引命中统计）
      const gx0 = Math.max(0, this.gx(x - r)), gx1 = Math.min(CW - 1, this.gx(x + r));
      const gz0 = Math.max(0, this.gz(z - r)), gz1 = Math.min(CH - 1, this.gz(z + r));
      // 逐格扫描（密集，改为全量粗筛：colliders 通常 < 1000）
      const cs = this.colliders;
      for (let i = 0; i < cs.length; i++) {
        const b = cs[i];
        if (b.maxX < x - r || b.minX > x + r || b.maxZ < z - r || b.minZ > z + r) continue;
        out.push(b);
      }
      return out;
    },

    // ---------- 地面高度 ----------
    // 返回脚底可站立高度（考虑平台顶面）
    groundAt: function (x, z) {
      let g = 0;
      const cs = this.colliders;
      for (let i = 0; i < cs.length; i++) {
        const b = cs[i];
        if (x < b.minX - 0.05 || x > b.maxX + 0.05 || z < b.minZ - 0.05 || z > b.maxZ + 0.05) continue;
        if (b.maxY > g) g = b.maxY;
      }
      return g;
    },

    // ---------- 线段 vs AABB (slab) ----------
    // 返回 t(0..1) 命中距离或 null
    rayBox: function (ox, oy, oz, dx, dy, dz, b) {
      const inv = (v) => (Math.abs(v) < 1e-9 ? 1e9 : 1 / v);
      const t1 = (b.minX - ox) * inv(dx), t2 = (b.maxX - ox) * inv(dx);
      const t3 = (b.minZ - oz) * inv(dz), t4 = (b.maxZ - oz) * inv(dz);
      const t5 = (b.minY - oy) * inv(dy), t6 = (b.maxY - oy) * inv(dy);
      const tmin = Math.max(Math.min(t1, t2), Math.min(t3, t4), Math.min(t5, t6));
      const tmax = Math.min(Math.max(t1, t2), Math.max(t3, t4), Math.max(t5, t6));
      if (tmax < 0 || tmin > tmax) return null;
      return tmin >= 0 ? tmin : tmax;
    },

    // ---------- 射线 vs 世界（静态碰撞体） ----------
    // 返回 {t, x,y,z, box, normal} 或 null
    rayWorld: function (ox, oy, oz, dx, dy, dz, maxT) {
      maxT = maxT || 200;
      let best = null;
      const cs = this.colliders;
      // 网格粗筛沿线
      const steps = Math.max(1, Math.ceil(maxT / (CELL * 0.9)));
      const cand = new Set();
      for (let s = 0; s <= steps; s++) {
        const t = (s / steps) * maxT;
        const x = ox + dx * t, z = oz + dz * t;
        const gx = this.gx(x), gz = this.gz(z);
        if (gx < 0 || gz < 0 || gx >= CW || gz >= CH) continue;
        // 邻域格里的 box
        if (this.grid[gz * CW + gx] !== 1) continue;
        const r = CELL;
        const gx0 = Math.max(0, gx - 1), gx1 = Math.min(CW - 1, gx + 1);
        const gz0 = Math.max(0, gz - 1), gz1 = Math.min(CH - 1, gz + 1);
        cand.add(gx + ',' + gz);
      }
      // 兜底：colliders 全扫（量不大）
      for (let i = 0; i < cs.length; i++) {
        const b = cs[i];
        const t = this.rayBox(ox, oy, oz, dx, dy, dz, b);
        if (t == null || t > maxT) continue;
        if (!best || t < best.t) {
          const hx = ox + dx * t - b.cx, hy = oy + dy * t - b.cy, hz = oz + dz * t - b.cz;
          let nx = 0, ny = 0, nz = 0;
          const ax = Math.abs(hx / b.hx), ay = Math.abs(hy / b.hy), az = Math.abs(hz / b.hz);
          if (ax >= ay && ax >= az) nx = hx > 0 ? 1 : -1;
          else if (ay >= az) ny = hy > 0 ? 1 : -1;
          else nz = hz > 0 ? 1 : -1;
          best = { t, x: ox + dx * t, y: oy + dy * t, z: oz + dz * t, box: b, nx, ny, nz };
        }
      }
      return best;
    },

    // ---------- 遮挡视线（关键：AI 感知 + 弹道穿墙） ----------
    canSee: function (ax, ay, az, bx, by, bz) {
      const dx = bx - ax, dy = by - ay, dz = bz - az;
      const len = Math.sqrt(dx * dx + dy * dy + dz * dz);
      if (len < 0.001) return true;
      const ux = dx / len, uy = dy / len, uz = dz / len;
      const maxT = len - 0.05;
      const h = this.rayWorld(ax, ay, az, ux, uy, uz, maxT);
      return h == null;
    },

    // 视线 + 高度采样（地形起伏）
    lineOfSight: function (a, b) {
      return this.canSee(a.x, a.y, a.z, b.x, b.y, b.z);
    },

    // ---------- 敌人 hitbox 射线（枪械命中） ----------
    // meshes: IS.Enemies.hitboxes (userData.enemy/part)
    rayEnemies: function (ox, oy, oz, dx, dy, dz, maxT, raycaster) {
      maxT = maxT || 180;
      const boxes = IS.Enemies && IS.Enemies.hitboxes;
      if (!boxes || !boxes.length) return null;
      // 用 Box3 近似（比全 raycaster 快很多）
      let best = null;
      const _b = new T.Box3(), _c = new T.Vector3(), _s = new T.Vector3();
      for (let i = 0; i < boxes.length; i++) {
        const m = boxes[i];
        if (!m.visible) continue;
        _b.setFromCenterAndSize(
          _c.set(m.position.x, m.position.y, m.position.z),
          _s.set(m.scale.x * (m.userData.hw || 0.5), m.scale.y * (m.userData.hh || 0.5), m.scale.z * (m.userData.hd || 0.5))
        );
        // 简化的 slab（用 box 数据）
        const t = this.rayBoxSlab(ox, oy, oz, dx, dy, dz, _b.min, _b.max);
        if (t == null || t > maxT) continue;
        if (!best || t < best.t) best = { t, obj: m, part: m.userData.part, enemy: m.userData.enemy };
      }
      return best;
    },

    rayBoxSlab: function (ox, oy, oz, dx, dy, dz, mn, mx) {
      const inv = (v) => (Math.abs(v) < 1e-9 ? 1e9 : 1 / v);
      const t1 = (mn.x - ox) * inv(dx), t2 = (mx.x - ox) * inv(dx);
      const t3 = (mn.y - oy) * inv(dy), t4 = (mx.y - oy) * inv(dy);
      const t5 = (mn.z - oz) * inv(dz), t6 = (mx.z - oz) * inv(dz);
      const tmin = Math.max(Math.min(t1, t2), Math.min(t3, t4), Math.min(t5, t6));
      const tmax = Math.min(Math.max(t1, t2), Math.max(t3, t4), Math.max(t5, t6));
      if (tmax < 0 || tmin > tmax) return null;
      return tmin >= 0 ? tmin : tmax;
    },

    // ---------- 综合射击射线 ----------
    // 优先敌人（更近者胜），否则世界
    shoot: function (ox, oy, oz, dx, dy, dz, maxT) {
      maxT = maxT || 220;
      const w = this.rayWorld(ox, oy, oz, dx, dy, dz, maxT);
      const e = this.rayEnemies(ox, oy, oz, dx, dy, dz, maxT);
      if (e && (!w || e.t < w.t)) {
        return { type: 'enemy', t: e.t, enemy: e.enemy, part: e.part, x: ox + dx * e.t, y: oy + dy * e.t, z: oz + dz * e.t };
      }
      if (w) {
        return { type: 'world', t: w.t, box: w.box, tag: w.box.tag, x: w.x, y: w.y, z: w.z, nx: w.nx, ny: w.ny, nz: w.nz };
      }
      return { type: 'miss', t: maxT, x: ox + dx * maxT, y: oy + dy * maxT, z: oz + dz * maxT };
    },

    update: function () {
      // 敌人空间哈希维护（供 AI 邻域）
      const h = this._hash; if (!h) return;
      h.clear();
      const list = IS.Enemies && IS.Enemies.list;
      if (list) for (let i = 0; i < list.length; i++) {
        const e = list[i];
        if (!e.alive) continue;
        h.add(e, e.pos.x, e.pos.z, 0.8);
      }
    },

    // 敌人邻域查询
    nearEnemies: function (x, z, r, out) { return this._hash.query(x, z, r, out); },
  };

  IS.Ray = Ray;
})();

// effects.js — 粒子池 / 曳光弹 / 火花 / 爆炸 / 弹痕 / 掉落物
(function () {
  const IS = globalThis.IS || (globalThis.IS = {});
  const T = globalThis.THREE;
  const Utils = IS.Utils;

  const FX = {
    scene: null, ready: false,
    pools: {}, active: [],
    tex: {},
    counters: { sparks: 0, smoke: 0, blood: 0, tracers: 0 },
    _v0: new T.Vector3(), _v1: new T.Vector3(), _v2: new T.Vector3(),
    _m4: new T.Matrix4(), _q: new T.Quaternion(),

    init: function (scene) {
      this.scene = scene;
      this.ready = true;
      this.tracerPool = null;
    },

    prebuild: function () {
      // 预热：空槽占位，避免首次 hiccup
      this.sparks(0, 0, 0, 1);
    },

    // 把贴图装配进来（materials 加载完调用）
    attachTex: function (tex) { this.tex = tex; },

    // ---------- 火花（Points） ----------
    sparks: function (x, y, z, count, color, spread, speed) {
      if (!this.scene) return;
      const n = Math.min(count || 12, IS.CFG.fx.sparks);
      const geo = new T.BufferGeometry();
      const pos = new Float32Array(n * 3), vel = new Float32Array(n * 3), col = new Float32Array(n * 3);
      const c = new T.Color(color == null ? 0xffaa33 : color);
      for (let i = 0; i < n; i++) {
        pos[i * 3] = x; pos[i * 3 + 1] = y; pos[i * 3 + 2] = z;
        const a = Math.random() * Math.PI * 2, e = Math.random() * Math.PI * 0.6;
        const sp = (speed || 6) * (0.4 + Math.random() * 0.8);
        vel[i * 3] = Math.cos(a) * Math.cos(e) * sp * (spread || 1);
        vel[i * 3 + 1] = Math.abs(Math.sin(e)) * sp * 1.2;
        vel[i * 3 + 2] = Math.sin(a) * Math.cos(e) * sp * (spread || 1);
        col[i * 3] = c.r * (0.7 + Math.random() * 0.3);
        col[i * 3 + 1] = c.g * (0.6 + Math.random() * 0.4);
        col[i * 3 + 2] = c.b * (0.4 + Math.random() * 0.4);
      }
      geo.setAttribute('position', new T.BufferAttribute(pos, 3));
      const mat = new T.PointsMaterial({ size: 0.08, vertexColors: true, transparent: true, opacity: 1, depthWrite: false, blending: T.AdditiveBlending, sizeAttenuation: true });
      const pts = new T.Points(geo, mat);
      pts.frustumCulled = false;
      this.scene.add(pts);
      this.active.push({ k: 'sparks', obj: pts, vel, life: 0, max: 0.45 + Math.random() * 0.25 });
      this.counters.sparks++;
      this._cap('sparks', 24);
    },

    _cap: function (k, max) {
      let c = 0;
      for (let i = 0; i < this.active.length; i++) if (this.active[i].k === k) c++;
      let kill = c - max;
      if (kill <= 0) return;
      for (let i = 0; i < this.active.length && kill > 0; i++) {
        if (this.active[i].k === k) { this._dispose(this.active[i]); this.active.splice(i, 1); kill--; i--; }
      }
    },

    // ---------- 烟团 ----------
    smoke: function (x, y, z, count, scale, dark) {
      if (!this.scene) return;
      const tex = this.tex.smoke || this.tex.glow;
      const n = Math.min(count || 8, IS.CFG.fx.smoke);
      for (let i = 0; i < n; i++) {
        const mat = new T.SpriteMaterial({ map: tex, transparent: true, opacity: 0.7, depthWrite: false, color: dark ? 0x333333 : 0xb0aca5 });
        const s = new T.Sprite(mat);
        const sc = (scale || 1) * (0.5 + Math.random() * 0.9);
        s.scale.set(sc, sc, sc);
        s.position.set(x + (Math.random() - 0.5) * 0.6, y + Math.random() * 0.4, z + (Math.random() - 0.5) * 0.6);
        s.frustumCulled = false;
        this.scene.add(s);
        this.active.push({ k: 'smoke', obj: s, vx: (Math.random() - 0.5) * 0.6, vy: 0.6 + Math.random() * 0.7, vz: (Math.random() - 0.5) * 0.6, life: 0, max: 1.6 + Math.random() * 1.4, rot: (Math.random() - 0.5) * 1.4, grow: 1.6 });
      }
      this._cap('smoke', 22);
    },

    // ---------- 血迹 ----------
    blood: function (x, y, z, count, dir) {
      if (!this.scene) return;
      const tex = this.tex.blood || this.tex.smoke;
      const n = Math.min(count || 14, IS.CFG.fx.blood);
      for (let i = 0; i < n; i++) {
        const mat = new T.SpriteMaterial({ map: tex, transparent: true, opacity: 0.95, depthWrite: false, color: 0x8a1418 });
        const s = new T.Sprite(mat);
        const sc = 0.12 + Math.random() * 0.22;
        s.scale.set(sc, sc, sc);
        s.position.set(x, y, z);
        s.frustumCulled = false;
        this.scene.add(s);
        const d = dir || { x: 0, y: 1, z: 0 };
        this.active.push({
          k: 'blood', obj: s,
          vx: d.x * 3 + (Math.random() - 0.5) * 4, vy: Math.abs(d.y) * 2 + Math.random() * 3, vz: d.z * 3 + (Math.random() - 0.5) * 4,
          life: 0, max: 0.7 + Math.random() * 0.6, grav: true,
        });
      }
      this._cap('blood', 18);
    },

    // ---------- 命中火花（按材质） ----------
    impact: function (x, y, z, nx, ny, nz, kind) {
      if (kind === 'flesh') {
        this.blood(x, y, z, 12, { x: nx, y: ny || 0.5, z: nz });
        IS.Audio && IS.Audio.at && IS.Audio.at('impact_flesh', x, y, z, 0.7);
      } else if (kind === 'metal') {
        this.sparks(x, y, z, 16, 0xffcc55, 1, 7);
        IS.Audio && IS.Audio.at && IS.Audio.at('impact_metal', x, y, z, 0.8);
        this.decal(x, y, z, nx, ny, nz, 'bullet', 0.12);
      } else if (kind === 'concrete') {
        this.sparks(x, y, z, 10, 0xbb9977, 1, 5);
        this.smoke(x, y, z, 3, 0.7, true);
        IS.Audio && IS.Audio.at && IS.Audio.at('impact_concrete', x, y, z, 0.8);
        this.decal(x, y, z, nx, ny, nz, 'scorch', 0.22);
      } else if (kind === 'glass') {
        this.sparks(x, y, z, 20, 0xaaddff, 1.2, 6);
        IS.Audio && IS.Audio.at && IS.Audio.at('impact_glass', x, y, z, 0.7);
      } else {
        this.sparks(x, y, z, 12, 0xffaa33, 1, 6);
        IS.Audio && IS.Audio.at && IS.Audio.at('impact', x, y, z, 0.6);
      }
    },

    // ---------- 曳光弹（细长发光条） ----------
    tracer: function (from, to, color, width) {
      if (!this.scene) return;
      const g = this._tracerGeo();
      const mat = new T.MeshBasicMaterial({
        color: color == null ? 0xffd27a : color, transparent: true, opacity: 0.9,
        blending: T.AdditiveBlending, depthWrite: false, side: T.DoubleSide,
      });
      const m = new T.Mesh(g, mat);
      const dx = to.x - from.x, dy = to.y - from.y, dz = to.z - from.z;
      const len = Math.sqrt(dx * dx + dy * dy + dz * dz);
      m.position.set((from.x + to.x) / 2, (from.y + to.y) / 2, (from.z + to.z) / 2);
      this._v0.set(dx, dy, dz).normalize();
      this._v1.set(0, 0, 1);
      this._q.setFromUnitVectors(this._v1, this._v0);
      m.quaternion.copy(this._q);
      const w = width || 0.02;
      m.scale.set(w, w, len);
      m.frustumCulled = false;
      this.scene.add(m);
      this.active.push({ k: 'tracer', obj: m, life: 0, max: 0.09 });
      this._cap('tracer', IS.CFG.fx.tracers);
      this.counters.tracers++;
    },

    _tracerGeo: function () {
      if (!this._tg) {
        // 单位长 Z 轴四边形（中心原点）
        const g = new T.BufferGeometry();
        g.setAttribute('position', new T.BufferAttribute(new Float32Array([-0.5, -0.5, 0, 0.5, -0.5, 0, 0.5, 0.5, 0, -0.5, 0.5, 0]), 3));
        g.setIndex([0, 1, 2, 0, 2, 3]);
        this._tg = g;
      }
      return this._tg;
    },

    // ---------- 爆炸 ----------
    explosion: function (x, y, z, power, color) {
      if (!this.scene) return;
      power = power || 1;
      // 火球
      const tex = this.tex.explosion || this.tex.glow;
      const mat = new T.SpriteMaterial({ map: tex, transparent: true, depthWrite: false, blending: T.AdditiveBlending, color: color || 0xffcc77 });
      const s = new T.Sprite(mat);
      s.position.set(x, y + 0.3, z);
      const sc0 = 0.5 * power;
      s.scale.set(sc0, sc0, sc0);
      s.frustumCulled = false;
      this.scene.add(s);
      this.active.push({ k: 'flash', obj: s, life: 0, max: 0.4, grow: 7 * power });

      // 闪光
      const fm = new T.SpriteMaterial({ map: this.tex.flash || tex, transparent: true, depthWrite: false, blending: T.AdditiveBlending, color: 0xffffff });
      const fs = new T.Sprite(fm); fs.position.set(x, y + 0.4, z); fs.scale.setScalar(2.2 * power); fs.frustumCulled = false;
      this.scene.add(fs);
      this.active.push({ k: 'flash', obj: fs, life: 0, max: 0.18, grow: 10 });

      // 火花 + 烟 + 弹坑
      this.sparks(x, y + 0.3, z, Math.floor(26 * power), 0xffaa44, 1.2, 11 * power);
      this.smoke(x, y + 0.6, z, Math.floor(10 * power), 1.4 * power);
      this.decal(x, 0.04, z, 0, 1, 0, 'scorch', 1.2 * power);

      // 物理冲击（击退 AI）
      const cx = x, cz = z, cy = y;
      const list = IS.Enemies && IS.Enemies.list;
      if (list) {
        const r = 6 * power;
        for (let i = 0; i < list.length; i++) {
          const e = list[i]; if (!e.alive) continue;
          const ddx = e.pos.x - cx, ddz = e.pos.z - cz, ddy = e.pos.y - cy;
          const d = Math.sqrt(ddx * ddx + ddz * ddz + ddy * ddy);
          if (d < r) {
            const f = (1 - d / r) * 18 * power;
            e.vel && (e.vel.x += (ddx / (d || 1)) * f, e.vel.y += 4 * (1 - d / r) * power, e.vel.z += (ddz / (d || 1)) * f);
            IS.Enemies.damage && IS.Enemies.damage(e, 60 * power * (1 - d / r) + 10, 'torso', cx, cy, cz);
          }
        }
      }
      // 玩家冲击
      const p = IS.Char && IS.Char.pos;
      if (p) {
        const ddx = p.x - cx, ddz = p.z - cz, ddy = p.y - cy;
        const d = Math.sqrt(ddx * ddx + ddz * ddz + ddy * ddy);
        if (d < 7 * power) {
          const f = (1 - d / (7 * power));
          IS.Char.applyImpulse && IS.Char.applyImpulse(ddx / (d || 1) * f * 12, f * 6, ddz / (d || 1) * f * 12);
          IS.Damage && IS.Damage.player && IS.Damage.player(Math.floor(40 * f * power));
          this._shakeScreen(f * 0.9);
        }
      }
      IS.Audio && IS.Audio.at && IS.Audio.at('explosion', x, y, z, Math.min(1, power));
      this._shakeScreen(0.35 * power, 0.5);
    },

    // ---------- 弹痕 / 弹壳 decal ----------
    decal: function (x, y, z, nx, ny, nz, kind, size) {
      if (!this.scene) return;
      const S = IS.state; if (!S.decals) S.decals = [];
      const geo = IS.Mat && IS.Mat.geo ? IS.Mat.geo.decal : new T.PlaneGeometry(1, 1);
      let mat;
      if (kind === 'blood') mat = IS.Mat && IS.Mat.mats ? IS.Mat.mats.decalBlood : new T.MeshBasicMaterial({ color: 0x881010, transparent: true });
      else if (kind === 'scorch') mat = IS.Mat && IS.Mat.mats ? IS.Mat.mats.decalScorch : new T.MeshBasicMaterial({ color: 0x110d0a, transparent: true });
      else mat = IS.Mat && IS.Mat.mats ? IS.Mat.mats.decalBullet : new T.MeshBasicMaterial({ color: 0x120d0a, transparent: true });
      const m = new T.Mesh(geo, mat);
      const s = size || 0.18;
      m.scale.set(s, s, s);
      m.position.set(x + nx * 0.012, y + ny * 0.012, z + nz * 0.012);
      // 朝向法线
      if (Math.abs(ny) > 0.9) {
        m.rotation.x = -Math.PI / 2;
      } else {
        const yaw = Math.atan2(nx, nz);
        m.rotation.y = yaw;
        m.rotation.x = 0;
        // 让平面贴墙：先竖起来再偏
        if (Math.abs(ny) > 0.05) m.rotation.x = ny * 0.2;
      }
      m.receiveShadow = false; m.castShadow = false;
      this.scene.add(m);
      S.decals.push({ obj: m, life: 0, max: kind === 'blood' ? 40 : 25 });
      // 上限
      if (S.decals.length > (IS.CFG.fx.decals || 160)) {
        const old = S.decals.shift();
        this._disposeDecal(old);
      }
    },

    // 掉落弹壳（视觉小道具，物理简化）
    shell: function (x, y, z, dir) {
      if (!this.scene || !IS.Mat) return;
      const geo = IS.Mat.geo.shell;
      const mat = IS.Mat.mats.metal || new T.MeshStandardMaterial({ color: 0xc9a227, metalness: 0.9, roughness: 0.35 });
      const m = new T.Mesh(geo, mat);
      m.position.set(x, y, z);
      m.rotation.set(Math.random() * Math.PI, Math.random() * Math.PI, Math.random() * Math.PI);
      m.castShadow = true;
      this.scene.add(m);
      this.active.push({ k: 'shell', obj: m, vx: dir.x + (Math.random() - 0.5), vy: 2 + Math.random() * 1.5, vz: dir.z + (Math.random() - 0.5), life: 0, max: 4.5, spin: (Math.random() - 0.5) * 20, bounce: 0 });
      this._cap('shell', 60);
    },

    // ---------- 屏幕震动 ----------
    _shakeScreen: function (amt, dur) {
      const W = IS.Weapons; if (!W) return;
      W.addShake && W.addShake(amt, dur || amt * 0.7);
    },

    // ---------- 更新 ----------
    update: function (dt) {
      const a = this.active;
      for (let i = a.length - 1; i >= 0; i--) {
        const p = a[i]; p.life += dt;
        const k = p.life / p.max;
        const o = p.obj;
        if (k >= 1) { this._dispose(p); a.splice(i, 1); continue; }
        if (p.k === 'sparks') {
          const pos = o.geometry.attributes.position;
          const arr = pos.array, vel = p.vel;
          for (let j = 0; j < arr.length; j += 3) {
            vel[j + 1] -= IS.CFG.gravity * -1 * dt * 0.8;
            arr[j] += vel[j] * dt; arr[j + 1] += vel[j + 1] * dt; arr[j + 2] += vel[j + 2] * dt;
            // 地面反弹
            if (arr[j + 1] < 0.02) { arr[j + 1] = 0.02; vel[j + 1] *= -0.35; vel[j] *= 0.6; vel[j + 2] *= 0.6; }
          }
          pos.needsUpdate = true;
          o.material.opacity = Math.pow(1 - k, 1.6);
        } else if (p.k === 'smoke') {
          o.position.x += p.vx * dt; o.position.y += p.vy * dt; o.position.z += p.vz * dt;
          p.vy *= 0.96;
          const g = 1 + p.grow * k;
          o.scale.multiplyScalar(1 + dt * p.grow * 0.6);
          o.material.opacity = 0.7 * Math.pow(1 - k, 1.4);
          o.material.rotation += p.rot * dt;
        } else if (p.k === 'blood') {
          p.vy += IS.CFG.gravity * dt;
          o.position.x += p.vx * dt; o.position.y += p.vy * dt; o.position.z += p.vz * dt;
          if (o.position.y < 0.02) {
            // 变成地面弹痕
            this.decal(o.position.x, 0.02, o.position.z, 0, 1, 0, 'blood', 0.2 + Math.random() * 0.2);
            o.material.opacity = 0; this._dispose(p); a.splice(i, 1); continue;
          }
          o.material.opacity = Math.pow(1 - k, 0.8);
        } else if (p.k === 'tracer') {
          o.material.opacity = 0.9 * Math.pow(1 - k, 2);
          o.scale.z *= 1 - dt * 1.5;
        } else if (p.k === 'flash') {
          const g = (p.grow || 6);
          const sc = o.userData.s0 != null ? o.userData.s0 : (o.userData.s0 = o.scale.x);
          o.scale.setScalar(sc + (g * p.max) * (1 - Math.pow(1 - k, 3)));
          o.material.opacity = Math.pow(1 - k, 2.4);
        } else if (p.k === 'shell') {
          p.vy += IS.CFG.gravity * dt * 0.6;
          o.position.x += p.vx * dt; o.position.y += p.vy * dt; o.position.z += p.vz * dt;
          o.rotation.x += p.spin * dt; o.rotation.z += p.spin * 0.7 * dt;
          if (o.position.y < 0.015) {
            if (p.bounce < 2) { p.vy = Math.abs(p.vy) * 0.32; p.vx *= 0.5; p.vz *= 0.5; p.bounce++; p.spin *= 0.4; }
            else { o.position.y = 0.012; p.vx = p.vy = p.vz = 0; }
          }
          o.material.opacity = k > 0.8 ? (1 - k) * 5 : 1;
          if (o.material.transparent === false) o.material.transparent = true;
        }
      }

      // decals 淡出
      const S = IS.state; if (S && S.decals) {
        for (let i = S.decals.length - 1; i >= 0; i--) {
          const d = S.decals[i]; d.life += dt;
          if (d.life > d.max) {
            const k2 = (d.life - d.max) / 2;
            if (d.obj.material) { if (!d.obj.material.transparent) { d.obj.material = d.obj.material.clone(); d.obj.material.transparent = true; } d.obj.material.opacity = Math.max(0, 1 - k2); }
            if (k2 >= 1) { this._disposeDecal(d); S.decals.splice(i, 1); }
          }
        }
      }
    },

    _dispose: function (p) {
      const o = p.obj; if (!o) return;
      if (o.parent) o.parent.remove(o);
      if (o.geometry && p.k !== 'tracer' && !o.geometry._shared) { try { o.geometry.dispose(); } catch (e) {} }
      if (o.material && !o.material._shared) { try { o.material.dispose(); } catch (e) {} }
    },
    _disposeDecal: function (d) {
      if (d && d.obj && d.obj.parent) d.obj.parent.remove(d.obj);
    },

    clear: function () {
      for (let i = this.active.length - 1; i >= 0; i--) this._dispose(this.active[i]);
      this.active.length = 0;
      const S = IS.state; if (S && S.decals) { for (let i = 0; i < S.decals.length; i++) this._disposeDecal(S.decals[i]); S.decals.length = 0; }
    },
  };

  IS.Effects = FX;
})();

// tools/harness.js — REAL-browser ground-truth boot test.
// Loads index.html's scripts IN ORDER into ONE jsdom window using the REAL
// vendored three.min.js (NOT a stub) + a requestAnimationFrame pump + canvas
// 2d stub + Image loader for assets/textures/*.png. Runs IS.boot(document),
// pumps rAF, and reports IS._stages[], first uncaught error + file:line + stack,
// whether a frame actually rendered, and whether the loop camera moved.
//
// Run:  cd <root> && node tools/harness.js
'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const htmlPath = path.join(ROOT, 'index.html');
const { JSDOM, VirtualConsole } = require('jsdom');

// ---------- capture real <script src> order from index.html ----------
const html = fs.readFileSync(htmlPath, 'utf8');
const srcRe = /<script[^>]*\bsrc=["']([^"']+)["'][^>]*><\/script>/gi;
const scripts = [];
let m;
while ((m = srcRe.exec(html)) !== null) {
  scripts.push(m[1]);
}

// ---------- canvas 2d stub (jsdom has no real canvas backend) ----------
function ctxGradient() {
  return { addColorStop: function () {} };
}
function make2D(canvas) {
  const ctx = {
    canvas: canvas,
    fillStyle: '#000', strokeStyle: '#000', lineWidth: 1, globalAlpha: 1,
    globalCompositeOperation: 'source-over', font: '10px sans-serif',
    textAlign: 'left', textBaseline: 'alphabetic', lineJoin: 'miter',
    lineCap: 'butt', imageSmoothingEnabled: true, shadowBlur: 0, shadowColor: '#000',
    filter: 'none', miterLimit: 10, strokeStyle: '#000',
    fillRect: function () {}, strokeRect: function () {}, clearRect: function () {},
    fill: function () {}, stroke: function () {}, beginPath: function () {}, closePath: function () {},
    moveTo: function () {}, lineTo: function () {}, arc: function () {}, arcTo: function () {},
    ellipse: function () {}, rect: function () {}, quadraticCurveTo: function () {},
    bezierCurveTo: function () {}, clip: function () {},
    save: function () {}, restore: function () {},
    translate: function () {}, rotate: function () {}, scale: function () {}, transform: function () {},
    setTransform: function () {}, resetTransform: function () {},
    createLinearGradient: ctxGradient, createRadialGradient: ctxGradient,
    createPattern: function () { return { setTransform: function () {} }; },
    drawImage: function () {}, putImageData: function () {},
    getImageData: function (x, y, w, h) {
      w = w || 1; h = h || 1;
      return { width: w, height: h, data: new Uint8ClampedArray(w * h * 4), colorSpace: 'srgb' };
    },
    createImageData: function (w, h) {
      w = w || 1; h = h || 1;
      return { width: w, height: h, data: new Uint8ClampedArray(w * h * 4), colorSpace: 'srgb' };
    },
    measureText: function (t) {
      const len = (t || '').length;
      return { width: len * 6, actualBoundingBoxLeft: 0, actualBoundingBoxRight: len * 6,
        actualBoundingBoxAscent: 8, actualBoundingBoxDescent: 2 };
    },
    fillText: function () {}, strokeText: function () {}, setLineDash: function () {}, getLineDash: function () { return []; },
  };
