// ---------- virtual console capture ----------
const vc = new VirtualConsole();
const consoleErrors = [];
vc.on('jsdomError', function (err) {
  const detail = err.detail || err.cause || err;
  consoleErrors.push({ kind: 'jsdomError', msg: err.message, stack: (detail && detail.stack) || err.stack });
});
vc.on('error', function (a) {
  consoleErrors.push({ kind: 'console.error', msg: String(a && a.message ? a.message : a) });
});

// ---------- build the window ----------
const dom = new JSDOM(html, {
  url: 'file://' + htmlPath,
  contentType: 'text/html',
  runScripts: 'dangerously',
  pretendToBeVisual: true,        // provides window.requestAnimationFrame + performance.now
  resources: undefined,           // do NOT auto-fetch; we inject scripts manually
  virtualConsole: vc,
});
const win = dom.window;
win.HTMLCanvasElement.prototype.getContext = function (type) {
  if (type === '2d') {
    const c = make2D(this);
    Object.defineProperty(this, '_is2d', { value: true });
    return c;
  }
  return null; // 'webgl'/'webgl2' -> let game renderer fallback path run
};

// real require of three.min.js -> inject into window, mark three loaded
try {
  require(path.join(ROOT, 'vendor', 'three.min.js'));
} catch (e) {
  console.log('THREE REQUIRE ERROR:', e.message);
}
win.THREE = (globalThis.THREE && globalThis.THREE.REVISION) ? globalThis.THREE : undefined;
win.IS = globalThis.IS && globalThis.IS.CFG ? globalThis.IS : undefined;
const THREE_OK = !!(win.THREE && win.THREE.REVISION);

// ---------- crash reporting ----------
const stageLog = [];           // everything routed through IS._diag / __dbg
let firstError = null;         // {msg, file, line, col, stack}
const renderStats = { count: 0 };

function recordError(src, e) {
  if (firstError) return;
  firstError = {
    msg: e && e.message ? e.message : String(e),
    stack: (e && e.stack) ? String(e.stack) : '',
    stage: stageLog.length ? stageLog[stageLog.length - 1] : null,
    src: src,
  };
}

// ---------- pump rAF in node ----------
function pump(frames, done) {
  let i = 0;
  (function next() {
    if (i++ >= frames) { return done(); }
    try { dom.window._virtualConsole; } catch (_) {}
    // pretendToBeVisual drives rAF via MessageChannel/timeout internally;
    // force a tick by calling any queued callbacks with a synthesized timestamp.
    const t = Date.now();
    try { dom.window._rAFTick && dom.window._rAFTick(t); } catch (_) {}
    setImmediate(next);
  })();
}

// ---------- inject script pipeline ----------
const threeRe = /three\.min\.js/i;
let idx = 0;
function injectNext() {
  if (idx >= scripts.length) { return finish(); }
  const rel = scripts[idx++];
  const full = path.join(ROOT, rel);

  // three.min.js: injected globally above (covers WebGLRenderer patch)
  if (threeRe.test(rel)) {
    if (THREE_OK) { injectNext(); return; }
    try { fs.readFileSync(full, 'utf8'); } catch (_) {}
    injectNext(); return;
  }

  let code;
  try {
    code = fs.readFileSync(full, 'utf8');
  } catch (e) {
    consoleErrors.push({ kind: 'readfail', msg: rel + ': ' + e.message });
    injectNext(); return;
  }

  const fname = rel.replace(/^.*\//, '') || 'inline';
  const prefixed = win.eval.bind ? undefined : undefined;
  try {
    const wrapped = ';(function(){\n' + code + '\n})();\n//# sourceURL=' + fname;
    win.eval(wrapped);
  } catch (e) {
    recordError(fname, e);
    stageLog.push('INJECT-ERR ' + fname + ' ' + e.message);
  }
  setImmediate(injectNext);
}

// ---------- finish: run IS.boot, pump, report ----------
function finish() {
  // instrument IS._diag / window.__dbg to capture stage tokens
  try {
    const IS = win.IS;
    if (IS && typeof IS.boot === 'function') {
      const origDiag = IS._diag;
      IS._diag = function (t) {
        stageLog.push('DIAG ' + t);
        try { if (origDiag) return origDiag(t); } catch (e) {}
      };
    }
  } catch (e) {}
  try {
    const origDbg = win.__dbg;
    win.__dbg = function (t) {
      stageLog.push('DBG ' + t);
      try { if (origDbg) return origDbg(t); } catch (e) {}
    };
  } catch (e) {}

  // patch renderer.render -> count real frames (real three only)
  try {
    if (win.THREE && win.THREE.WebGLRenderer && win.THREE.WebGLRenderer.prototype && !win.THREE.WebGLRenderer.prototype.render.__harness) {
      const pr = win.THREE.WebGLRenderer.prototype.render;
      const wrapped = function () {
        renderStats.count++;
        return pr.apply(this, arguments);
      };
      wrapped.__harness = true;
      win.THREE.WebGLRenderer.prototype.render = wrapped;
    }
  } catch (e) {}

  // ensure a diag box exists (game creates its own lazily)
  if (!win.document.getElementById('dbg')) {
    const d = win.document.createElement('div');
    d.id = 'dbg';
    win.document.body.appendChild(d);
  }

  // call IS.boot(document)
  try {
    win.IS.boot(win.document);
    stageLog.push('boot() returned');
  } catch (e) {
    recordError('IS.boot', e);
  }

  // pump animation frames + run pending timers so safety-net & loop tick
  const t0 = Date.now();
  const MAXMS = 8000;
  const FFRAMES = 400;

  function runLoop() {
    // force jsdom's rAF queue to drain
    try { dom.window._rAFTick && dom.window._rAFTick(Date.now()); } catch (_) {}
    if (Date.now() - t0 < MAXMS) {
      setImmediate(runLoop);
    } else {
      report();
    }
  }
  runLoop();
}

function report() {
  const IS = win.IS || globalThis.IS || {};
  const out = [];
  out.push('==== IRON SIEGE HARNESS REPORT ====');
  out.push('THREE loaded: ' + THREE_OK + (win.THREE ? ' r' + win.THREE.REVISION : ''));
  out.push('IS present:   ' + !!IS);
  out.push('IS.boot type: ' + typeof IS.boot);
  out.push('_booted:      ' + IS._booted);
  out.push('_loadStuck:   ' + IS._loadStuck);
  out.push('renders:      ' + renderStats.count);

  // camera
  const cam = IS.camera || (win.IS && win.IS.camera) || null;
  if (cam && cam.position) {
    const p = cam.position.toArray ? cam.position.toArray() : [cam.position.x, cam.position.y, cam.position.z];
    const zero = !p[0] && !p[1] && !p[2];
    out.push('camera pos:   [' + p[0].toFixed(2) + ',' + p[1].toFixed(2) + ',' + p[2].toFixed(2) + '] ' + (zero ? '(ZERO)' : '(moved)'));
  } else {
    out.push('camera pos:   (no IS.camera found)');
  }

  // stage log tail
  out.push('---- stage log (' + stageLog.length + ' lines) ----');
  const tail = stageLog.slice(-40);
  tail.forEach(function (l) { out.push('  ' + l); });

  // error tail
  out.push('---- errors ----');
  if (firstError) {
    out.push('FIRST UNCAUGHT [' + firstError.src + '] stage=' + firstError.stage);
    out.push('  msg: ' + firstError.msg);
    out.push('  first stack frame: ' + ((firstError.stack || '').split('\n')[1] || '').trim());
  } else {
    out.push('  (no uncaught error captured)');
  }
  consoleErrors.slice(0, 20).forEach(function (e) {
    out.push('  [' + e.kind + '] ' + e.msg + (e.stack ? (' | firstframe ' + ((e.stack).split('\n')[1] || '').trim()) : ''));
  });

  const txt = out.join('\n');
  process.stdout.write(txt + '\n');
  process.exit(firstError || !IS._booted ? 2 : 0);
}

// begin pipeline
if (!THREE_OK) {
  console.log('WARNING: real three.min.js did not register global THREE.REVISION.');
}
injectNext();

//离线材质贴图生成器：纯 Node，手写 PNG（无第三方依赖）。
// 生成的贴图放到 assets/textures/，游戏运行时用 THREE.TextureLoader 加载。
const fs = require('fs');
const zlib = require('zlib');

// ---- PNG 编码 ----
function crc32(buf) {
  let table = crc32.table;
  if (!table) {
