        } else { log('NOT BOOTED raf='+rafCount); }
        var fx=(IS._fxlog&&IS._fxlog())||'-';
        if(IS._fxlog) log('fx='+fx);
        var can=document.querySelector('canvas'); if(can) log('canvas '+can.width+'x'+can.height);
      }
    })();
  })();
  </script>

STEP 3 — add FX log to src/fx/effects.js. Read the file to find its namespace/`update` method and its live-count field (likely `this.active` or a pool). APPEND near the end:
  <FXobj>._fxlog = function(){ var a=this.active||this.pool||[]; var k={}; for(var i=0;i<a.length;i++){var t=(a[i]&&(a[i].type||a[i].kind||'?'))||'?'; k[t]=(k[t]||0)+1;} return 'scene='+!!(this.scene)+' live='+a.length+' types='+JSON.stringify(k); };
Adapt <FXobj> to the real var (e.g. IS.Effects).

STEP 4 — the KEY FIX: do NOT use multi-pass post-processing until the scene provably renders. In src/game/main.js find makePost() and the loop's render call. Make rendering SIMPLE and robust:
  - Set CFG.quality default to 'low' OR force the post chain off for now.
  - In loop(), replace the render line with a guarded direct render:
      try { renderer.render(scene, camera); } catch(e){ __dbg('RENDER ERR '+e.message); }
  - Keep shadows ON initially but add a fallback: if renderer creation throws, log it.

STEP 5 — force FIRST-FRAME content so we see SOMETHING. In createScene(), right after creating scene, set:
    scene.background = new THREE.Color(0x0b1020);
  and add a bright ground + fog test:
    scene.fog = new THREE.Fog(0x0b1020, 1, 140);
  and after map load, if no ground mesh added, add:
    (function(){var g=new THREE.Mesh(new THREE.PlaneGeometry(400,400),new THREE.MeshStandardMaterial({color:0x7a7f88,roughness:1}));g.rotation.x=-Math.PI/2;scene.add(g);})();
  Verify a PerspectiveCamera IS created; if any camera is null at render time, create one here:
    if(!camera){ camera=new THREE.PerspectiveCamera(75, innerWidth/innerHeight, 0.1, 800); camera.position.set(18,1.7,18); }
  and ensure camera.position is set (e.g. 18,1.7,18) BEFORE first render.

STEP 6 — node --check src/game/main.js; node --check src/fx/effects.js

REPORT (short, exact):
step1_three_ok: yes/no (+ first error if no)
makePost_present: yes/no ; changed_to_direct_render: yes/no
background_added: yes/no
camera_ok: yes/no (was it null? what pos?)
syntax_ok: main/effects
count_field: what you named live fx count
three.min.js: REAL or STUB (one line: how you tell)
nothing_else

