// utils.js — math / pooling helpers
(function () {
  const IS = globalThis.IS || (globalThis.IS = {});
  const T = globalThis.THREE;

  const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
  const lerp = (a, b, t) => a + (b - a) * t;
  const damp = (a, b, l, dt) => lerp(a, b, 1 - Math.exp(-l * dt));
  const rand = (a, b) => a + Math.random() * (b - a);
  const randInt = (a, b) => (a + Math.random() * (b - a + 1)) | 0;
  const pick = (arr) => arr[(Math.random() * arr.length) | 0];
  const sign = (v) => (v < 0 ? -1 : v > 0 ? 1 : 0);

  // rad shortest path
  function angDelta(a, b) {
    let d = (b - a) % (Math.PI * 2);
    if (d > Math.PI) d -= Math.PI * 2;
    if (d < -Math.PI) d += Math.PI * 2;
    return d;
  }
  function dampAngle(a, b, l, dt) { return a + angDelta(a, b) * (1 - Math.exp(-l * dt)); }

  // 简单 xorshift
  let _s = 0x9e3779b9;
  function noise1(x) {
    let n = Math.sin(x * 127.1) * 43758.5453;
    return n - Math.floor(n);
  }

  // 对象池
  function Pool(factory, reset, initial) {
    this.f = factory; this.r = reset || null; this.free = [];
    if (initial) for (let i = 0; i < initial; i++) this.free.push(factory());
  }
  Pool.prototype.get = function () {
    const o = this.free.length ? this.free.pop() : this.f();
    return o;
  };
  Pool.prototype.put = function (o) {
    if (this.r) this.r(o);
    if (this.free.length < 4096) this.free.push(o);
  };

  // 空间哈希（碰撞 / AI 邻域）
  function SpatialHash(cell) {
    this.cell = cell || 4; this.map = new Map();
  }
  SpatialHash.prototype._k = function (x, z) {
    return ((x / this.cell) | 0) + ',' + ((z / this.cell) | 0);
  };
  SpatialHash.prototype.clear = function () { this.map.clear(); };
  SpatialHash.prototype.add = function (obj, x, z, r) {
    r = r || 0.5;
    const c0x = ((x - r) / this.cell) | 0, c1x = ((x + r) / this.cell) | 0;
    const c0z = ((z - r) / this.cell) | 0, c1z = ((z + r) / this.cell) | 0;
    for (let cx = c0x; cx <= c1x; cx++) for (let cz = c0z; cz <= c1z; cz++) {
      const k = cx + ',' + cz; let a = this.map.get(k);
      if (!a) { a = []; this.map.set(k, a); }
      a.push(obj);
    }
  };
  SpatialHash.prototype.query = function (x, z, r, out) {
    out = out || []; out.length = 0;
    const c0x = ((x - r) / this.cell) | 0, c1x = ((x + r) / this.cell) | 0;
    const c0z = ((z - r) / this.cell) | 0, c1z = ((z + r) / this.cell) | 0;
    for (let cx = c0x; cx <= c1x; cx++) for (let cz = c0z; cz <= c1z; cz++) {
      const a = this.map.get(cx + ',' + cz);
      if (a) for (let i = 0; i < a.length; i++) if (out.indexOf(a[i]) < 0) out.push(a[i]);
    }
    return out;
  };

  IS.Utils = { clamp, lerp, damp, rand, randInt, pick, sign, angDelta, dampAngle, noise1, Pool, SpatialHash };
})();

// input.js — mouse look / keys / pointer lock
(function () {
  const IS = globalThis.IS || (globalThis.IS = {});
  const Utils = IS.Utils;

  const Input = {
    yaw: 0, pitch: 0,
    forward: 0, right: 0, jump: false, crouch: false, sprint: false,
    fire: false, reload: false, interact: false,
    mouseDX: 0, mouseDY: 0, wheel: 0,
    sensitivity: 0.0022, invertY: false,
    locked: false,
    onPauseChange: null,
    onWeaponSelect: null,
    _keys: {},

    init: function (dom) {
      const cv = dom.canvas || document.getElementById('viewport');
      document.addEventListener('mousemove', (e) => {
        if (!this.locked) return;
        this.mouseDX += e.movementX;
        this.mouseDY += e.movementY;
      });
      document.addEventListener('mousedown', (e) => {
        if (!this.locked) return;
        if (e.button === 0) this.fire = true;
        if (e.button === 2) this.aim = true;
      });
      document.addEventListener('mouseup', (e) => {
        if (e.button === 0) this.fire = false;
        if (e.button === 2) this.aim = false;
      });
      document.addEventListener('contextmenu', (e) => e.preventDefault());
      document.addEventListener('wheel', (e) => { this.wheel += Math.sign(e.deltaY); }, { passive: true });
      document.addEventListener('keydown', (e) => this._onKey(e, true));
      document.addEventListener('keyup', (e) => this._onKey(e, false));
      document.addEventListener('pointerlockchange', () => {
        this.locked = document.pointerLockElement === cv;
        if (!this.locked) this.fire = this.aim = false;
        if (this.onPauseChange) this.onPauseChange(!this.locked);
      });
    },

    _onKey: function (e, down) {
      const c = e.code;
      if (['KeyW','KeyA','KeyS','KeyD','Space','ShiftLeft','ControlLeft','KeyR','KeyE','KeyC','Tab']
          .indexOf(c) >= 0) e.preventDefault();
      this._keys[c] = down;
      if (!down) return;
      if (c === 'Escape') { this.unlock(); return; }
      if (c === 'Digit1' && this.onWeaponSelect) this.onWeaponSelect(0);
      if (c === 'Digit2' && this.onWeaponSelect) this.onWeaponSelect(1);
      if (c === 'Digit3' && this.onWeaponSelect) this.onWeaponSelect(2);
      if (c === 'Digit4' && this.onWeaponSelect) this.onWeaponSelect(3);
      if (c === 'Digit5' && this.onWeaponSelect) this.onWeaponSelect(4);
      if (c === 'KeyR') this.reload = true;
      if (c === 'KeyE') this.interact = true;
    },

    lock: function () {
      const cv = document.getElementById('viewport');
      if (cv.requestPointerLock) cv.requestPointerLock();
    },
    unlock: function () { if (document.exitPointerLock) document.exitPointerLock(); },

    // look consume
    updateLook: function () {
      this.yaw -= this.mouseDX * this.sensitivity;
      this.pitch -= this.mouseDY * this.sensitivity * (this.invertY ? -1 : 1);
      this.pitch = Utils.clamp(this.pitch, -1.5, 1.5);
      this.mouseDX = this.mouseDY = 0;
    },

    update: function () {
      const k = this._keys;
      this.forward = (k.KeyW ? 1 : 0) - (k.KeyS ? 1 : 0);
      this.right = (k.KeyD ? 1 : 0) - (k.KeyA ? 1 : 0);
      this.jump = !!k.Space;
      this.crouch = !!k.ControlLeft || !!k.KeyC;
      this.sprint = !!k.ShiftLeft && !this.crouch && this.forward > 0;
      if (this.aim) this.updateLook();
    },

    consume: function () {
      this.reload = false; this.interact = false; this.wheel = 0;
    },
  };

  IS.Input = Input;
})();

// audio.js — WebAudio procedural SFX (零外部音频资源)
(function () {
  const IS = globalThis.IS || (globalThis.IS = {});
  const Audio = {
    ctx: null, master: null, sfxBus: null, musicBus: null,
    listenerReady: false, started: false,
    _buffers: {}, _active: 0, _max: 28,

    init: function () {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      const ctx = new AC({ latencyHint: 'interactive' });
      this.ctx = ctx;
      this.master = ctx.createGain(); this.master.gain.value = 0.85;
      this.sfxBus = ctx.createGain(); this.sfxBus.gain.value = 0.9;
      this.musicBus = ctx.createGain(); this.musicBus.gain.value = 0.28;
      // 简易主总线压缩，防爆音
      const comp = ctx.createDynamicsCompressor();
      comp.threshold.value = -14; comp.knee.value = 22; comp.ratio.value = 6;
      comp.attack.value = 0.003; comp.release.value = 0.22;
      this.sfxBus.connect(comp); this.musicBus.connect(comp);
      comp.connect(this.master); this.master.connect(ctx.destination);
      this._makeReverb();
      this.buildBanks();
    },

    resume: function () { if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume(); },

    // 短脉冲混响（IIR 生成）
    _makeReverb: function () {
      const ctx = this.ctx; const cv = ctx.createConvolver();
      const len = Math.floor(ctx.sampleRate * 1.1);
      const buf = ctx.createBuffer(2, len, ctx.sampleRate);
      for (let ch = 0; ch < 2; ch++) {
        const d = buf.getChannelData(ch);
        for (let i = 0; i < len; i++) {
          const t = i / len;
          d[i] = (Math.random() * 2 - 1) * Math.pow(1 - t, 2.6);
        }
      }
      cv.buffer = buf;
      this.reverb = cv;
      const wet = ctx.createGain(); wet.gain.value = 0.18;
      cv.connect(wet); wet.connect(this.master);
      this.reverbSend = wet;
    },

    resize: function () {},

    // ---------- 采样库合成 ----------
    buildBanks: function () {
      const ctx = this.ctx; if (!ctx) return;
      const sr = ctx.sampleRate;
      const B = this._buffers;

      function render(dur, fn) {
        const n = Math.floor(sr * dur);
        const buf = ctx.createBuffer(1, n, sr);
        const d = buf.getChannelData(0);
        for (let i = 0; i < n; i++) d[i] = fn(i / sr, i / n);
        return buf;
      }
      const noise = () => Math.random() * 2 - 1;

      B.shot_rifle = render(0.34, (t, k) => {
        const env = Math.pow(1 - k, 7);
        const body = Math.sin(2 * Math.PI * (170 * Math.pow(1 - k, 2) + 55) * t);
        const crack = noise() * Math.pow(1 - k, 16);
        return (body * 0.5 + crack * 0.85) * env;
      });
      B.shot_pistol = render(0.26, (t, k) => {
        const env = Math.pow(1 - k, 6);
        return (Math.sin(2 * Math.PI * 130 * Math.pow(1 - k, 1.6) * t) * 0.5 + noise() * Math.pow(1 - k, 12) * 0.7) * env;
      });
      B.shot_smg = render(0.16, (t, k) => {
        const env = Math.pow(1 - k, 9);
        return (Math.sin(2 * Math.PI * 200 * (1 - k) * t) * 0.4 + noise() * Math.pow(1 - k, 20) * 0.7) * env;
      });
      B.shot_shotgun = render(0.5, (t, k) => {
        const env = Math.pow(1 - k, 4.5);
        const boom = Math.sin(2 * Math.PI * 70 * Math.pow(1 - k, 1.2) * t) * 0.8;
        return (boom + noise() * Math.pow(1 - k, 6) * 0.9) * env;
      });
      B.shot_sniper = render(0.7, (t, k) => {
        const crack = noise() * Math.pow(1 - k, 24);
        const boom = Math.sin(2 * Math.PI * 90 * Math.pow(1 - k, 1.4) * t) * 0.7;
        const echo = noise() * Math.pow(1 - k, 1.2) * 0.18 * Math.sin(t * 40);
        return (crack * 1.0 + boom + echo) * Math.pow(1 - k, 3);
      });
      B.shot_lmg = render(0.3, (t, k) => {
        const env = Math.pow(1 - k, 8);
        return (Math.sin(2 * Math.PI * 110 * (1 - k) * t) * 0.6 + noise() * Math.pow(1 - k, 14) * 0.8) * env;
      });
      B.shot_plasma = render(0.4, (t, k) => {
        const f = 1400 * Math.pow(1 - k, 2.4) + 180;
        const env = Math.pow(1 - k, 5);
        return (Math.sin(2 * Math.PI * f * t) * 0.4 + (noise() * 0.3) * Math.pow(1 - k, 10)) * env;
      });
      B.shot_rail = render(0.9, (t, k) => {
        const f = 240 * Math.exp(-t * 3) + 900 * Math.exp(-t * 8);
        const env = Math.pow(1 - k, 2.2);
        return (Math.sin(2 * Math.PI * f * t) * 0.55 + noise() * Math.pow(1 - k, 30) * 0.6) * env;
      });
      B.impact = render(0.14, (t, k) => noise() * Math.pow(1 - k, 22) * 0.7);
      B.impact_flesh = render(0.2, (t, k) => {
        const body = Math.sin(2 * Math.PI * (90 * Math.pow(1 - k, 1.5)) * t);
        return (body * 0.6 + noise() * Math.pow(1 - k, 10) * 0.35) * Math.pow(1 - k, 5);
      });
      B.impact_metal = render(0.3, (t, k) => {
        const ring = Math.sin(2 * Math.PI * 1800 * t) * Math.exp(-t * 26)
          + Math.sin(2 * Math.PI * 2650 * t) * Math.exp(-t * 30);
        return (ring * 0.5 + noise() * Math.pow(1 - k, 18) * 0.5) * Math.pow(1 - k, 2);
      });
      B.impact_concrete = render(0.24, (t, k) => {
        return (noise() * Math.pow(1 - k, 14) * 0.8 + Math.sin(2 * Math.PI * 160 * (1 - k) * t) * 0.2) * Math.pow(1 - k, 3);
      });
      B.impact_glass = render(0.34, (t, k) => {
        let s = noise() * Math.pow(1 - k, 8);
        for (let i = 0; i < 4; i++) s += Math.sin(2 * Math.PI * (1200 + i * 700) * t) * Math.exp(-t * (18 + i * 6)) * 0.25;
        return s * 0.4;
      });
      B.reload = render(0.4, (t, k) => {
        const click = (t > 0.05 && t < 0.07) || (t > 0.22 && t < 0.25);
        return noise() * (click ? 0.6 : 0.02) * Math.pow(1 - k, 2) * (click ? 1 : 0);
      });
      B.dry = render(0.1, (t, k) => noise() * Math.pow(1 - k, 30) * 0.4);
      B.hurt = render(0.4, (t, k) => (Math.sin(2 * Math.PI * (180 - k * 60) * t) * 0.4 + noise() * Math.pow(1 - k, 8) * 0.3) * Math.pow(1 - k, 3));
      B.explosion = render(1.4, (t, k) => {
        const boom = Math.sin(2 * Math.PI * (60 * Math.exp(-t * 2.4) + 28) * t);
        const blast = noise() * Math.pow(1 - k, 2.2);
        const crack = noise() * Math.pow(1 - k, 18);
        return (boom * 0.85 + blast * 0.9 + crack * 0.7) * Math.pow(1 - k, 1.6);
      });
      B.enemy_hurt = render(0.24, (t, k) => (Math.sin(2 * Math.PI * (300 - k * 120) * t) * 0.35 + noise() * Math.pow(1 - k, 9) * 0.25) * Math.pow(1 - k, 4));
      B.enemy_die = render(0.7, (t, k) => {
        const sweep = Math.sin(2 * Math.PI * (240 - k * 170) * t);
        return (sweep * 0.4 + noise() * Math.pow(1 - k, 5) * 0.3) * Math.pow(1 - k, 2.4);
      });
      B.robot_hurt = render(0.2, (t, k) => {
        const f = 700 + Math.sin(t * 90) * 300;
        return (Math.sin(2 * Math.PI * f * t) * 0.3 + noise() * Math.pow(1 - k, 16) * 0.5) * Math.pow(1 - k, 6);
      });
      B.robot_die = render(1.0, (t, k) => {
        const f = 900 * Math.exp(-t * 4) + 120;
        const spark = noise() * Math.pow(1 - k, 3) * (Math.random() > 0.5 ? 1 : 0.3);
        return (Math.sin(2 * Math.PI * f * t) * 0.4 + spark * 0.5) * Math.pow(1 - k, 2);
      });
      B.step = render(0.13, (t, k) => noise() * Math.pow(1 - k, 26) * 0.28);
      B.land = render(0.24, (t, k) => (Math.sin(2 * Math.PI * 80 * (1 - k) * t) * 0.5 + noise() * Math.pow(1 - k, 16) * 0.4) * Math.pow(1 - k, 4));
      B.pickup = render(0.3, (t, k) => {
        const f = 660 * Math.pow(1 - k, 0.4) + 240;
        return Math.sin(2 * Math.PI * f * t) * Math.pow(1 - k, 4) * 0.4;
      });
      B.ui = render(0.09, (t, k) => Math.sin(2 * Math.PI * 880 * t) * Math.pow(1 - k, 12) * 0.25);
      B.alert = render(0.5, (t, k) => {
        const f = 440 + (Math.floor(t * 12) % 2 ? 160 : 0);
        return Math.sin(2 * Math.PI * f * t) * Math.pow(1 - k, 2) * 0.35;
      });
      B.grenade_bounce = render(0.12, (t, k) => noise() * Math.pow(1 - k, 24) * 0.35);
      B.switch = render(0.1, (t, k) => (noise() * Math.pow(1 - k, 20) + Math.sin(2 * Math.PI * 520 * t) * Math.pow(1 - k, 14)) * 0.3);
      // 敌人语音（合成吼叫）
      B.roar_human = render(0.7, (t, k) => {
        const f = 140 + Math.sin(t * 24) * 40;
        return (Math.sin(2 * Math.PI * f * t) * 0.4 + noise() * 0.25) * Math.pow(1 - k, 1.8);
      });
      B.roar_brute = render(1.1, (t, k) => {
        const f = 70 + Math.sin(t * 14) * 26;
        return (Math.sin(2 * Math.PI * f * t) * 0.7 + Math.sin(2 * Math.PI * f * 1.5 * t) * 0.25 + noise() * 0.2) * Math.pow(1 - k, 1.4);
      });
      B.roar_robot = render(0.8, (t, k) => {
        const f = 220 + Math.sin(t * 40) * 120;
        return ((Math.sin(2 * Math.PI * f * t) > 0 ? 1 : -1) * 0.28 + noise() * 0.18) * Math.pow(1 - k, 1.6);
      });
    },

    // ---------- 播放 ----------
    play: function (name, opt) {
      if (!this.ctx) return;
      if (this.ctx.state === 'suspended') return;
      const buf = this._buffers[name]; if (!buf) return;
      if (this._active > this._max) return;
      opt = opt || {};
      const ctx = this.ctx;
      const src = ctx.createBufferSource(); src.buffer = buf;
      const g = ctx.createGain();
      const vol = (opt.vol != null ? opt.vol : 1);
      g.gain.value = vol;
      src.playbackRate.value = opt.rate || 1;

      let node = src;
      if (opt.pan != null || opt.dist != null) {
        const p = ctx.createStereoPanner ? ctx.createStereoPanner() : null;
        const filt = ctx.createBiquadFilter(); filt.type = 'lowpass';
        if (opt.dist != null) {
          const d = opt.dist;
          const cf = Math.max(500, 16000 * Math.exp(-d / 90));
          filt.frequency.value = cf;
          g.gain.value = vol * Math.exp(-d / 110);
        } else filt.frequency.value = 18000;
        node.connect(filt);
        if (p) { p.pan.value = opt.pan || 0; filt.connect(p); p.connect(this.sfxBus); }
        else filt.connect(this.sfxBus);
        if (this.reverbSend && opt.dist > 14) { const w = ctx.createGain(); w.gain.value = Math.min(0.5, opt.dist / 160); filt.connect(w); w.connect(this.reverb); }
      } else {
        node.connect(g); g.connect(this.sfxBus);
      }
      if (opt.pan != null) { const gg = src; }
      src.connect(g);
      const t0 = ctx.currentTime + (opt.delay || 0);
      try { src.start(t0); } catch (e) { return; }
      this._active++;
      src.onended = () => { this._active--; };
    },

    // 3D 位置音
    at: function (name, x, y, z, vol) {
      if (!this.ctx) return;
      const L = this.listenerPos;
      let pan = 0, dist = 0;
      if (L) {
        const fx = Math.sin(-L.yaw), fz = Math.cos(-L.yaw);
        const dx = x - L.x, dz = z - L.z;
        pan = Math.max(-1, Math.min(1, (dx * Math.cos(-L.yaw) - dz * Math.sin(-L.yaw)) / 9));
        dist = Math.sqrt(dx * dx + dz * dz + (y - L.y) * (y - L.y));
      }
      this.play(name, { vol: vol == null ? 1 : vol, pan, dist });
    },

    listenerPos: { x: 0, y: 1.6, z: 0, yaw: 0 },
    setListener: function (x, y, z, yaw) { const L = this.listenerPos; L.x = x; L.y = y; L.z = z; L.yaw = yaw; },

    startAmbient: function () {
      if (!this.ctx || this.started) return;
      this.started = true;
      const ctx = this.ctx;
      // 低频风声
      const n = ctx.createBufferSource();
      const len = Math.floor(ctx.sampleRate * 4);
      const buf = ctx.createBuffer(1, len, ctx.sampleRate);
      const d = buf.getChannelData(0);
      let last = 0;
      for (let i = 0; i < len; i++) { const w = Math.random() * 2 - 1; last = (last + 0.02 * w) / 1.02; d[i] = last * 3.5; }
      n.buffer = buf; n.loop = true;
      const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 380;
      const g = ctx.createGain(); g.gain.value = 0.16;
      const lfo = ctx.createOscillator(); lfo.frequency.value = 0.08;
      const lfoG = ctx.createGain(); lfoG.gain.value = 0.07;
      lfo.connect(lfoG); lfoG.connect(g.gain);
      n.connect(lp); lp.connect(g); g.connect(this.musicBus);
      n.start(); lfo.start();
      this._amb = { n, g, lp };
      this.startMusic();
    },

    startMusic: function () {
      if (!this.ctx) return;
      const ctx = this.ctx; const self = this;
      this._music = { next: ctx.currentTime + 0.1, step: 0 };
      const scale = [0, 3, 5, 7, 10, 12, 15];
      function tick() {
        if (!self._music) return;
        const now = ctx.currentTime;
        while (self._music.next < now + 1.2) {
          const s = self._music.step;
          const root = 55 * Math.pow(2, ((s >> 3) % 3) / 12);
          // drone
          if (s % 16 === 0) self._note(root, 3.6, 0.18, 'sawtooth', 260);
          // pulse bass
          if (s % 4 === 0) self._note(root * 2, 0.5, 0.10, 'square', 180);
          // arpeggio tension
          if (s % 2 === 0) {
            const idx = scale[(s * 3 + ((s >> 2) % 4)) % scale.length];
            self._note(root * 4 * Math.pow(2, idx / 12), 0.42, 0.045, 'triangle', 2400);
          }
          self._music.next += 0.30;
          self._music.step++;
        }
        self._musicTimer = setTimeout(tick, 700);
      }
      tick();
    },

    _note: function (freq, dur, vol, type, cutoff) {
      const ctx = this.ctx;
      const o = ctx.createOscillator(); o.type = type || 'sawtooth'; o.frequency.value = freq;
      const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = cutoff || 1200;
      const g = ctx.createGain();
      const t = ctx.currentTime;
      g.gain.setValueAtTime(0, t);
      g.gain.linearRampToValueAtTime(vol, t + 0.06);
      g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      o.connect(f); f.connect(g); g.connect(this.musicBus);
      o.start(t); o.stop(t + dur + 0.02);
    },

    intensity: function (v) {
      if (!this.ctx || !this._amb) return;
      this._amb.lp.frequency.value = 320 + v * 700;
      this._amb.g.gain.value = 0.14 + v * 0.10;
    },
  };

  IS.Audio = Audio;
})();

