ops.content:
.viewport {
  position: absolute; inset: 0; display: block; width: 100%; height: 100%;
}

/* IRON SIEGE — HUD 스타일 */
html, body { margin:0; padding:0; width:100%; height:100%; overflow:hidden; background:#000; font-family:'Segoe UI',system-ui,sans-serif; }
canvas { display:block; }
#hud { position:absolute; inset:0; pointer-events:none; color:#cfe3ff; text-shadow:0 1px 2px #000; }

/* 크로스헤어 */
.xhair { position:absolute; left:50%; top:50%; width:0; height:0; }
.xhair .dot { position:absolute; left:-1.5px; top:-1.5px; width:3px; height:3px; border-radius:50%; background:#7dffb0; }
.xhair .ln { position:absolute; background:#7dffb0; width:2px; height:8px; margin-left:-1px; transform-origin:center; }

/* 하단 무기/탄약 */
.ammo { position:absolute; right:28px; bottom:24px; text-align:right; }
.ammo .mag { font-size:44px; font-weight:700; letter-spacing:2px; }
.ammo .res { font-size:20px; opacity:.65; }
.ammo .wname { font-size:13px; letter-spacing:3px; text-transform:uppercase; opacity:.8; color:#ffd27a; }

/* 체력/방어 */
.vitals { position:absolute; left:28px; bottom:24px; width:260px; }
.bar { height:14px; background:rgba(255,255,255,.10); border:1px solid rgba(255,255,255,.25); position:relative; overflow:hidden; margin-bottom:6px; }
.bar>i { position:absolute; inset:0; transform-origin:left; background:linear-gradient(90deg,#2bff88,#0f8);
  transition:transform .12s linear; }
.bar.hp>i { background:linear-gradient(90deg,#ff5b5b,#ff8a4a); }
.bar>i.crit { animation:crit .7s infinite; }
@keyframes crit { 0%,100%{opacity:1} 50%{opacity:.35} }
.vlabel { font-size:11px; letter-spacing:2px; opacity:.75; }

/* 상단 웨이브/점수 */
.wave { position:absolute; left:50%; top:18px; transform:translateX(-50%); text-align:center; }
.wave .n { font-size:30px; font-weight:700; color:#ffd27a; letter-spacing:4px; }
.wave .sub { font-size:12px; opacity:.7; letter-spacing:3px; }

/* 미니맵 */
.minimap { position:absolute; right:22px; top:22px; width:180px; height:180px;
  border:1px solid rgba(125,255,176,.4); background:rgba(5,12,8,.55); border-radius:4px; }

/* 킬피드 */
.killfeed { position:absolute; right:22px; top:210px; width:280px; text-align:right; font-size:13px; }
.killfeed .row { opacity:.9; margin:3px 0; color:#ff9a6a; }
.killfeed .hs { color:#ffd27a; font-weight:700; }

/* 피격 방향 */
.dmgdir { position:absolute; left:50%; top:50%; width:0; height:0; }
.dmgdir .arc { position:absolute; left:-60px; top:-160px; width:120px; height:320px;
  border:6px solid transparent; border-top-color:rgba(255,60,60,.9); border-radius:50%; opacity:0; }

/* 저체력 비네트 */
.vignette { position:absolute; inset:0; pointer-events:none; opacity:0;
  box-shadow:inset 0 0 220px 60px rgba(180,0,0,.75); }
.vignette.on { animation:vn 1.1s infinite; }
@keyframes vn { 0%,100%{opacity:.25} 50%{opacity:.7} }

/* 재정집 */
.reload { position:absolute; left:50%; top:58%; transform:translateX(-50%); width:200px; text-align:center; opacity:0; }
.reload.on { opacity:1; }
.reload .bar { height:4px; }
.reload .bar>i { background:#ffd27a; }

/* 메뉴 */
.menu { position:absolute; inset:0; display:flex; flex-direction:column; align-items:center; justify-content:center;
  background:radial-gradient(ellipse at center,rgba(10,16,28,.82),rgba(2,4,8,.94)); pointer-events:auto; }
.menu h1 { font-size:72px; letter-spacing:14px; margin:0; color:#ffd27a;
  text-shadow:0 0 24px rgba(255,140,60,.6); }
.menu h2 { margin:.4em 0 1.4em; font-size:14px; letter-spacing:8px; opacity:.7; color:#8fb7ff; font-weight:400; }
.btn { pointer-events:auto; cursor:pointer; padding:14px 42px; margin-top:18px; font-size:16px; letter-spacing:5px;
  color:#0b0f16; background:linear-gradient(180deg,#ffd27a,#ff8a3c); border:0; border-radius:3px; font-weight:700; }
.btn:hover { filter:brightness(1.12); }
.keys { margin-top:26px; font-size:12px; line-height:2; opacity:.7; text-align:center; letter-spacing:1px; }
.keys b { color:#7dffb0; font-weight:600; }
.hidden { display:none !important; }

/* 감지/알림 */
.alert { position:absolute; left:50%; top:38%; transform:translateX(-50%); font-size:22px; letter-spacing:10px;
  color:#ff6a6a; opacity:0; font-weight:700; }
.alert.on { animation:al 1.6s ease-out; }
@keyframes al { 0%{opacity:0;transform:translateX(-50%) scale(.8)} 20%{opacity:1} 80%{opacity:.8} 100%{opacity:0} }

/* 디버그 */
.dbg { position:absolute; left:10px; top:10px; font-size:11px; opacity:.55; font-family:ui-monospace,monospace; }

// char.js — 플레이어 컨트롤러 (碰撞 / 이동 / 상태 / 데미지)
(function () {
  const IS = globalThis.IS || (globalThis.IS = {});
  const T = globalThis.THREE;
  const U = IS.Utils;
  const C = IS.CFG.player;

  const Char = {
    pos: new T.Vector3(18, 0, 18),
    vel: new T.Vector3(),
    yaw: 0, pitch: 0,
    hp: 100, armor: 0, alive: true,
    grounded: true, crouching: false, sprinting: false,
    height: C.eye, radius: C.radius,
    bob: 0, bobPhase: 0, stepAcc: 0,
    camera: null, eyeObj: null,
    landVel: 0,

    init: function (camera, x, z) {
      this.camera = camera;
      this.pos.set(x, IS.Ray ? IS.Ray.groundAt(x, z) : 0, z);
      camera.fov = IS.CFG.fov;
      camera.near = 0.08; camera.far = 700;
      camera.updateProjectionMatrix();
      if (!this._savedSens) this._savedSens = IS.Input.sensitivity;
    },

    respawn: function (x, z) {
      this.pos.set(x, IS.Ray ? IS.Ray.groundAt(x, z) : 0, z);
      this.vel.set(0, 0, 0);
      this.hp = C.hp; this.armor = 0; this.alive = true;
      this.yaw = 0; this.pitch = 0;
    },

    applyImpulse: function (x, y, z) {
      this.vel.x += x; this.vel.y += y; this.vel.z += z;
      this.grounded = false;
    },

    //外面调用：受伤
    hurt: function (amount, fromX, fromZ) {
      if (!this.alive || IS.state.god) return;
      let dmg = amount;
      if (this.armor > 0) {
        const abs = Math.min(this.armor, dmg * 0.6);
        this.armor -= abs; dmg -= abs;
      }
      this.hp -= dmg;
      IS.HUD && IS.HUD.damageDir && IS.HUD.damageDir(Math.atan2((fromX||0) - this.pos.x, -((fromZ||0) - this.pos.z)));
      IS.Audio && IS.Audio.play && IS.Audio.play('hurt', { vol: 0.6 });
      if (this.hp <= 0) { this.hp = 0; this.die(); }
    },

    heal: function (v) { this.hp = Math.min(C.hp, this.hp + v); },
    giveArmor: function (v) { this.armor = Math.min(C.armorMax, this.armor + v); },

    die: function () {
      this.alive = false;
      IS.state.over = true;
      IS.gameOver && IS.gameOver();
    },

    update: function (dt) {
      const inp = IS.Input;
      if (!this.alive) { this.syncCamera(dt); return; }

      this.yaw = inp.yaw;
      this.pitch = inp.pitch;

      // 蹲伏高度过渡
      const wantCrouch = inp.crouch;
      this.crouching = wantCrouch;
      const targetH = wantCrouch ? C.crouchEye : C.eye;
      this.height = U.damp(this.height, targetH, 14, dt);

      // 地面
      const groundY = IS.Ray ? IS.Ray.groundAt(this.pos.x, this.pos.z) : 0;

      // 移动意图（相机偏航 평면）
      let f = inp.forward, r = inp.right;
      const mag = Math.sqrt(f * f + r * r);
      if (mag > 1) { f /= mag; r /= mag; }
      const sy = Math.sin(this.yaw), cy = Math.cos(this.yaw);
      // forward = -Z when yaw=0 (three convention)
      let wx = (f * sy) + (r * cy);
      let wz = (-f * cy) + (r * sy);

      let speed = C.walk;
      if (this.crouching) speed = C.crouch;
      else if (inp.sprint && mag > 0.1) speed = C.sprint;
      else if (inp.aim) speed = C.walk * 0.55;
      else if (mag > 0.1) speed = C.run;
      this.sprinting = inp.sprint && !this.crouching && mag > 0.1 && !inp.aim;

      const accel = this.grounded ? C.accel : C.accel * C.air;
      const wishX = wx * speed, wishZ = wz * speed;
      // ground damping
      const curX = this.vel.x, curZ = this.vel.z;
      let dx = wishX - curX, dz = wishZ - curZ;
      const curSpeed = Math.sqrt(curX * curX + curZ * curZ);
      const wishSpeed = Math.sqrt(wishX * wishX + wishZ * wishZ);
      let accelSpeed = this.grounded ? Math.min(accel * dt, wishSpeed > 0 ? wishSpeed : Math.max(0, curSpeed)) : (accel * dt);
      if (wishSpeed > 0) {
        const ns = Math.min(wishSpeed, curSpeed + accelSpeed);
        if (curSpeed > 0.001) {
          const ox = curX / curSpeed, oz = curZ / curSpeed;
          const tx = wishX / (wishSpeed || 1), tz = wishZ / (wishSpeed || 1);
          const bx = tx * (ns - curSpeed), bz = tz * (ns - curSpeed);
          this.vel.x = ox * curSpeed + bx;
          this.vel.z = oz * curSpeed + bz;
        } else {
          this.vel.x = tx * ns; this.vel.z = tz * ns;
        }
      } else {
        const dec = Math.min(curSpeed, C.decel * dt);
        if (curSpeed > 0.001) { this.vel.x -= (curX / curSpeed) * dec; this.vel.z -= (curZ / curSpeed) * dec; }
      }

      // 점프
      if (inp.jump && this.grounded) {
        this.vel.y = C.jump;
        this.grounded = false;
        IS.Audio && IS.Audio.play && IS.Audio.play('land', { vol: 0.25, rate: 1.4 });
      }

      // 중력
      this.vel.y += IS.CFG.gravity * dt;

      // 位置积分
      const nx = this.pos.x + this.vel.x * dt;
      const ny = this.pos.y + this.vel.y * dt;
      const nz = this.pos.z + this.vel.z * dt;

      // 台阶上升：脚部检测
      const foot = this.pos.y;
      let stepped = false;
      if (this.grounded) {
        const g2 = IS.Ray ? IS.Ray.groundAt(nx, nz) : 0;
        if (g2 - foot <= C.stepHeight && g2 > foot) {
          this.pos.y = g2; stepped = true;
        }
      }

      // 落地
      const gY = IS.Ray ? IS.Ray.groundAt(nx, nz) : 0;
      this.pos.x = nx; this.pos.z = nz;
      if (ny <= gY) {
        if (!this.grounded && this.vel.y < -6) {
          const hard = Math.min(1, Math.abs(this.vel.y) / 16);
          IS.Audio && IS.Audio.play && IS.Audio.play('land', { vol: 0.25 + hard * 0.5 });
          IS.Effects && IS.Effects._shakeScreen && IS.Effects._shakeScreen(hard * 0.35);
          this.landVel = hard;
        }
        this.pos.y = gY;
        this.vel.y = 0;
        this.grounded = true;
      } else if (stepped === false && this.grounded && ny > gY + 0.02) {
        // 走下台阶
        this.pos.y = ny;
        this.grounded = false;
      } else {
        this.pos.y = ny;
        this.grounded = false;
      }

      // 碰撞求解（圆 vs AABB）
      if (IS.Ray) {
        const p = { x: this.pos.x, y: this.pos.y, z: this.pos.z };
        IS.Ray.resolve(p, this.radius, Math.max(0.6, this.height - 0.1));
        // 仅水平推出
        this.pos.x = p.x; this.pos.z = p.z;
        if (Math.abs(p.y - this.pos.y) > 0.001 && p.y > this.pos.y) {
          // 顶到天花板
          this.pos.y = Math.min(this.pos.y, p.y);
          if (this.vel.y > 0) this.vel.y = 0;
        }
      }

      // 世界边界
      this.pos.x = U.clamp(this.pos.x, -95, 95);
      this.pos.z = U.clamp(this.pos.z, -95, 95);

      // 视角后坐/震动
      const W = IS.Weapons;
      const rkP = W && W.recoilPitch ? W.recoilPitch : 0;
      const rkY = W && W.recoilYaw ? W.recoilYaw : 0;

      // 头bob
      const planar = Math.sqrt(this.vel.x * this.vel.x + this.vel.z * this.vel.z);
      if (this.grounded && planar > 0.5) {
        this.bobPhase += dt * (8 + planar * 0.8);
        this.bob = U.damp(this.bob, 1, 8, dt);
        // 脚步声
        this.stepAcc += planar * dt;
        const stride = this.sprinting ? 2.4 : (this.crouching ? 3.6 : 2.9);
        if (this.stepAcc > stride) {
          this.stepAcc = 0;
          IS.Audio && IS.Audio.play && IS.Audio.play('step', { vol: this.crouching ? 0.12 : 0.3, rate: 0.9 + Math.random() * 0.25 });
        }
      } else {
        this.bob = U.damp(this.bob, 0, 6, dt);
      }
      const bobAmt = this.sprinting ? 0.055 : (this.crouching ? 0.02 : 0.035);
      const bobY = Math.sin(this.bobPhase) * bobAmt * this.bob;
      const bobX = Math.cos(this.bobPhase * 0.5) * bobAmt * 0.8 * this.bob;

      // 音频 listener
      IS.Audio && IS.Audio.setListener && IS.Audio.setListener(this.pos.x, this.pos.y + this.height, this.pos.z, this.yaw);

      this.syncCameraParams(this.pos.y + this.height + bobY, bobX, rkP, rkY);

      // 低体力音乐紧张度
      IS.Audio && IS.Audio.intensity && IS.Audio.intensity(U.clamp((100 - this.hp) / 100, 0, 1));
    },

    syncCameraParams: function (eyeY, roll, rkP, rkY) {
      const cam = this.camera; if (!cam) return;
      cam.position.set(this.pos.x, eyeY, this.pos.z);
      cam.rotation.order = 'YXZ';
      cam.rotation.y = this.yaw + rkY;
      cam.rotation.x = U.clamp(this.pitch + rkP, -1.5, 1.5);
      cam.rotation.z = (roll || 0) * 0.35 + (IS.Weapons && IS.Weapons.rollOffset ? IS.Weapons.rollOffset : 0);
      cam.updateMatrixWorld();
    },

    syncCamera: function (dt) {
      const cam = this.camera; if (!cam) return;
      this.syncCameraParams(this.pos.y + this.height, 0, 0, 0);
    },

    // 相机前方向量（供射击）
    getForward: function (out) {
      const cam = this.camera;
      if (cam) { cam.getWorldDirection(out); return out; }
      return out.set(0, 0, -1);
    },

    getEye: function (out) {
      return out.set(this.pos.x, this.pos.y + this.height, this.pos.z);
    },

    // 外部：死亡落体
    updateCorpse: function (dt) {
      if (this.alive) return;
      this.pitch = U.damp(this.pitch, -1.4, 3, dt);
      this.syncCameraParams(this.pos.y + 0.25, 0.6, 0, 0);
    },

    // 主循环扩展点（掉血条幅）
    hudUpdate: function () {
      IS.HUD && IS.HUD.setHealth && IS.HUD.setHealth(Math.ceil(this.hp), C.hp);
      IS.HUD && IS.HUD.setArmor && IS.HUD.setArmor(Math.ceil(this.armor), C.armorMax);
    },
  };

  IS.Char = Char;

  // 伤害总线（外部系统用）
  IS.Damage = {
    player: function (amount, fx, fz) { Char.hurt(amount, fx, fz); },
  };
})();

// spawner.js — 敌人波次导演 + 掉落物 + 补给生成
(function () {
  const IS = globalThis.IS || (globalThis.IS = {});
  const T = globalThis.THREE;
  const U = IS.Utils;

  const Spawner = {
    wave: 1, alive: 0, budget: 0, queue: [],
    nextAt: 0, intermission: 0, active: false,
    pickups: [], pickupGroup: null,
    difficulty: 'normal',
    _timer: 0, _hudTick: 0,

    init: function () {
      this.pickupGroup = new T.Group();
      IS.scene && IS.scene.add(this.pickupGroup);
      this.buildPickupMeshes();
    },

    // ---------- 掉落物 ----------
    buildPickupMeshes: function () {
      const geo = new T.BoxGeometry(0.5, 0.5, 0.5);
      const cGeo = new T.CylinderGeometry(0.35, 0.35, 0.55, 10);
      this._proto = {
        health: { geo: geo, color: 0xff4444, emissive: 0xff2222 },
        ammo: { geo: cGeo, color: 0xffaa33, emissive: 0xff8811 },
        armor: { geo: geo, color: 0x3399ff, emissive: 0x2277ff },
        grenade: { geo: new T.SphereGeometry(0.22, 10, 8), color: 0x66cc66, emissive: 0x22aa44 },
      };
    },

    spawnPickup: function (type, x, z) {
      const p = this._proto[type]; if (!p) return;
      const mat = new T.MeshStandardMaterial({ color: p.color, emissive: p.emissive, emissiveIntensity: 1.6, roughness: 0.4, metalness: 0.3 });
      const m = new T.Mesh(p.geo, mat);
      const y = (IS.Ray ? IS.Ray.groundAt(x, z) : 0) + 0.5;
      m.position.set(x, y, z);
      m.castShadow = true;
      this.pickupGroup.add(m);
      // 光柱
      const beam = new T.Mesh(new T.CylinderGeometry(0.28, 0.42, 3.2, 10, 1, true),
        new T.MeshBasicMaterial({ color: p.color, transparent: true, opacity: 0.16, depthWrite: false, side: T.DoubleSide }));
      beam.position.set(x, y + 1.1, z);
      this.pickupGroup.add(beam);
      this.pickups.push({ type, mesh: m, beam, x, z, y, phase: Math.random() * 6.28, life: 30 });
    },

    // ---------- 波次配置 ----------
    waveComp: function (n) {
      const diffMul = this.difficulty === 'easy' ? 0.7 : (this.difficulty === 'hard' ? 1.35 : 1);
      const budget = Math.floor((8 + n * 4) * diffMul);
      const comp = [];
      // 解锁表
      const pool = ['grunt'];
      if (n >= 2) pool.push('rusher');
      if (n >= 3) pool.push('heavy');
      if (n >= 4) pool.push('sniper');
      if (n >= 5) pool.push('drone');
      if (n >= 6) pool.push('shield');
      if (n >= 7) pool.push('cloaker');
      // Boss 每 5 波
      const hasBoss = n % 5 === 0;
      let left = budget;
      // boss 优先占预算
      if (hasBoss) { comp.push('brute'); left -= 8; }
      const w = { grunt: 1.0, rusher: 1.2, heavy: 1.8, sniper: 1.5, drone: 1.1, shield: 1.7, cloaker: 1.4 };
      let guard = 0;
      while (left > 0 && guard++ < 400) {
        const t = pool[(Math.random() * pool.length) | 0];
        const cost = w[t] || 1;
        if (cost > left + 0.5) continue;
        comp.push(t); left -= cost;
      }
      return comp;
    },

    reset: function () {
      this.wave = 0; this.alive = 0; this.queue.length = 0;
      this.active = false; this.intermission = 2.5;
      this.difficulty = IS.CFG.difficulty || 'normal';
      // 清掉落物
      for (let i = 0; i < this.pickups.length; i++) {
        const pk = this.pickups[i];
        if (pk.mesh.parent) pk.mesh.parent.remove(pk.mesh);
        if (pk.beam.parent) pk.beam.parent.remove(pk.beam);
      }
      this.pickups.length = 0;
    },

    onWave: function (n) { this.startWave(n); },

    startWave: function (n) {
      this.wave = n;
      const comp = this.waveComp(n);
      this.queue = comp.slice();
      this.aliveTarget = comp.length;
      this.active = true;
      this.nextAt = 0.5;
      this.intermission = 0;
      IS.HUD && IS.HUD.setWave && IS.HUD.setWave(n);
      IS.HUD && IS.HUD.announceWave && IS.HUD.announceWave(n);
      IS.Audio && IS.Audio.play && IS.Audio.play('alert', { vol: 0.5 });
    },

    // ---------- 每帧 ----------
    update: function (dt) {
      this._timer += dt;
      this._hudTick += dt;

      // 掉落物旋转 + 拾取
      this.updatePickups(dt);

      if (!this.active) {
        this.intermission -= dt;
        if (this.intermission <= 0 && IS.state.started && !IS.state.over) {
          this.startWave(this.wave + 1);
        }
        return;
      }

      const px = IS.Char ? IS.Char.pos.x : 0;
      const pz = IS.Char ? IS.Char.pos.z : 0;

      // 出怪节流
      this.nextAt -= dt;
      if (this.nextAt <= 0 && this.queue.length) {
        const maxAlive = IS.CFG.ai.maxActive;
        const cur = IS.Enemies && IS.Enemies.list ? IS.Enemies.list.filter(function (e) { return e.alive; }).length : 0;
        if (cur < maxAlive) {
          const type = this.queue.shift();
          // 远离玩家生成
          let sp = null;
          for (let k = 0; k < 24; k++) {
            const a = Math.random() * Math.PI * 2;
            const r = 38 + Math.random() * 34;
            const x = px + Math.cos(a) * r, z = pz + Math.sin(a) * r;
            if (Math.abs(x) > 92 || Math.abs(z) > 92) continue;
            if (IS.Nav && IS.Nav.isBlocked && IS.Nav.isBlocked(x, z)) continue;
            sp = { x: x, z: z }; break;
          }
          if (!sp) sp = { x: px + 40, z: pz };
          const e = IS.Enemies.spawn(type, sp.x, sp.z);
          if (e) {
            IS.Sensors && IS.Sensors.noise && IS.Sensors.noise(sp.x, sp.z, 26, 'spawn');
          }
          const gap = Math.max(0.28, 1.4 - this.wave * 0.06);
          this.nextAt = gap + Math.random() * 0.5;
        } else {
          this.nextAt = 0.6;
        }
      }

      // 波次完成判定
      const list = IS.Enemies && IS.Enemies.list ? IS.Enemies.list : [];
      let aliveNow = 0;
      for (let i = 0; i < list.length; i++) if (list[i].alive) aliveNow++;
      this.alive = aliveNow;
      IS.state.botsAlive = aliveNow;

      if (this.queue.length === 0 && aliveNow === 0) {
        this.active = false;
        this.intermission = IS.CFG.wave.intermission || 8;
        IS.HUD && IS.HUD.setState && IS.HUD.setState('WAVE ' + this.wave + ' CLEAR');
        IS.Audio && IS.Audio.play && IS.Audio.play('pickup', { vol: 0.5, rate: 0.7 });
        // 奖励补给
        this.dropWaveRewards(px, pz);
        IS.nextWave && IS.nextWave();
      }

      // HUD 状态刷新（低频）
      if (this._hudTick > 0.2) {
        this._hudTick = 0;
        if (this.active) IS.HUD && IS.HUD.setState && IS.HUD.setState('HOSTILES: ' + (aliveNow + this.queue.length));
      }
    },

    dropWaveRewards: function (px, pz) {
      const n = 3;
      for (let i = 0; i < n; i++) {
        const a = Math.random() * Math.PI * 2, r = 4 + Math.random() * 6;
        const x = U.clamp(px + Math.cos(a) * r, -92, 92);
        const z = U.clamp(pz + Math.sin(a) * r, -92, 92);
        this.spawnPickup(i === 0 ? 'health' : (i === 1 ? 'ammo' : 'armor'), x, z);
      }
    },

    // ---------- 敌人死亡回调（由 enemies.js 调用） ----------
    onKill: function (enemy) {
      const t = enemy && enemy.type;
      const px = IS.Char ? IS.Char.pos.x : 0;
      const pz = IS.Char ? IS.Char.pos.z : 0;
      const x = enemy ? enemy.pos.x : px, z = enemy ? enemy.pos.z : pz;
      if (Math.abs(x) > 92 || Math.abs(z) > 92) return;
      let type = null;
      const lowHp = IS.Char && IS.Char.hp < 45;
      if (lowHp && Math.random() < 0.28) type = 'health';
      else if (t === 'heavy' || t === 'brute' || t === 'shield') type = Math.random() < 0.5 ? 'ammo' : 'armor';
      else if (Math.random() < 0.16) type = 'ammo';
      else if (Math.random() < 0.06) type = 'grenade';
      if (type) this.spawnPickup(type, x, z);

      // 分数
      const sc = { grunt: 100, rusher: 140, heavy: 220, sniper: 200, drone: 130, shield: 240, cloaker: 260, brute: 1200 };
      IS.state.score = (IS.state.score || 0) + (sc[t] || 100);
      IS.state.kills = (IS.state.kills || 0) + 1;
      IS.state.streak = (IS.state.streak || 0) + 1;
    },

    updatePickups: function (dt) {
      const px = IS.Char ? IS.Char.pos.x : 0;
      const pz = IS.Char ? IS.Char.pos.z : 0;
      const py = IS.Char ? IS.Char.pos.y : 0;
      for (let i = this.pickups.length - 1; i >= 0; i--) {
        const pk = this.pickups[i];
        pk.life -= dt;
        pk.phase += dt * 2.4;
        pk.mesh.rotation.y += dt * 1.6;
        pk.mesh.position.y = pk.y + Math.sin(pk.phase) * 0.12;
        if (pk.beam) pk.beam.rotation.y += dt * 0.6;

        // 拾取检测
        const dx = px - pk.x, dz = pz - pk.z;
        const near = dx * dx + dz * dz < 1.4 && Math.abs(py - pk.y) < 2.2;
        if (near && IS.Char && IS.Char.alive) { this.collect(pk); this.remove(i); continue; }
        if (pk.life <= 0) {
          // 闪烁提示后消失
          if (pk.life < -2) { this.remove(i); continue; }
          const bl = Math.sin(pk.phase * 8) > 0;
          pk.mesh.visible = bl; if (pk.beam) pk.beam.visible = bl;
        }
      }
    },

    remove: function (i) {
      const pk = this.pickups[i];
      if (pk.mesh.parent) pk.mesh.parent.remove(pk.mesh);
      if (pk.beam.parent) pk.beam.parent.remove(pk.beam);
      if (pk.mesh.material) pk.mesh.material.dispose();
      if (pk.beam && pk.beam.material) pk.beam.material.dispose();
      this.pickups.splice(i, 1);
    },

    collect: function (pk) {
      const C = IS.CFG.player;
      let txt = '';
      if (pk.type === 'health') {
        if (IS.Char.hp >= C.hp) { IS.Weapons && IS.Weapons.giveAmmo && IS.Weapons.giveAmmo(30); txt = '+AMMO'; }
        else { IS.Char.heal(35); txt = '+HEALTH'; }
      } else if (pk.type === 'ammo') {
        IS.Weapons && IS.Weapons.giveAmmo && IS.Weapons.giveAmmo(60); txt = '+AMMO';
      } else if (pk.type === 'armor') {
        IS.Char.giveArmor(50); txt = '+ARMOR';
      } else if (pk.type === 'grenade') {
        IS.Weapons && IS.Weapons.giveGrenade && IS.Weapons.giveGrenade(1); txt = '+LAUNCHER AMMO';
      }
      IS.state.score = (IS.state.score || 0) + 25;
      IS.Audio && IS.Audio.play && IS.Audio.play('pickup', { vol: 0.6, rate: 1.1 });
      IS.HUD && IS.HUD.setState && IS.HUD.setState(txt);
      IS.HUD && IS.HUD.flashPickup && IS.HUD.flashPickup(pk.type);
      IS.Effects && IS.Effects.sparks && IS.Effects.sparks(pk.x, pk.y + 0.4, pk.z, 12, 0x88ffcc, 1, 4);
    },

    clear: function () {
      for (let i = this.pickups.length - 1; i >= 0; i--) this.remove(i);
      this.queue.length = 0; this.active = false;
    },
  };

  IS.Spawner = Spawner;
})();

# 轻量材质贴图生成器 v2（Node 纯 stdlib，零依赖）
