// tools/harness.js — REAL-browser ground-truth boot test.
// Loads index.html's scripts IN ORDER into ONE jsdom window using the REAL
// vendored three.min.js (NOT a stub) + requestAnimationFrame pump + canvas 2d
// stub + Image load for assets/textures/*.png. Runs IS.boot(document), pumps
// rAF, reports IS._stages[] + first uncaught error + file:line + stack, frame
// render count, and loop camera position.
//
// Run:  cd <root> && node tools/harness.js
'use strict';
const fs = require('fs');
const path = require('path');
const vm = require('vm');
const { JSDOM, VirtualConsole } = require('jsdom');

const ROOT = path.resolve(__dirname, '..');
const htmlPath = path.join(ROOT, 'index.html');
const threePath = path.join(ROOT, 'vendor', 'three.min.js');
const TEX_DIR = path.join(ROOT, 'assets', 'textures');

// ---------- script order from index.html ----------
const html = fs.readFileSync(htmlPath, 'utf8');
const srcRe = /<script[^>]*\bsrc=["']([^"']+)["'][^>]*><\/script>/gi;
const scripts = [];
let _m;
while ((_m = srcRe.exec(html)) !== null) scripts.push(_m[1]);
const threeRel = scripts.find(function (s) { return /three\.min\.js/i.test(s); });
const gameScripts = scripts.filter(function (s) { return s !== threeRel; });

// ---------- context-free 2d stub (jsdom has no canvas backend) ----------
function make2D(canvas) {
  const grad = { addColorStop: function () {} };
  return {
    canvas: canvas, fillStyle: '#000', strokeStyle: '#000', lineWidth: 1, globalAlpha: 1,
    globalCompositeOperation: 'source-over', font: '10px sans-serif', textAlign: 'left',
    textBaseline: 'alphabetic', lineJoin: 'miter', lineCap: 'butt', imageSmoothingEnabled: true,
    shadowBlur: 0, shadowColor: '#000', filter: 'none', miterLimit: 10,
    fillRect: function () {}, strokeRect: function () {}, clearRect: function () {},
    fill: function () {}, stroke: function () {}, beginPath: function () {}, closePath: function () {},
    moveTo: function () {}, lineTo: function () {}, arc: function () {}, arcTo: function () {},
    ellipse: function () {}, rect: function () {}, quadraticCurveTo: function () {},
    bezierCurveTo: function () {}, clip: function () {}, save: function () {}, restore: function () {},
    translate: function () {}, rotate: function () {}, scale: function () {}, transform: function () {},
    setTransform: function () {}, resetTransform: function () {},
    createLinearGradient: function () { return grad; }, createRadialGradient: function () { return grad; },
    createPattern: function () { return { setTransform: function () {} }; },
    drawImage: function () {}, putImageData: function () {},
    getImageData: function (x, y, w, h) { w = w || 1; h = h || 1; return { width: w, height: h, data: new Uint8ClampedArray(w * h * 4), colorSpace: 'srgb' }; },
    createImageData: function (w, h) { w = w || 1; h = h || 1; return { width: w, height: h, data: new Uint8ClampedArray(w * h * 4), colorSpace: 'srgb' }; },
    measureText: function (t) { const l = (t || '').length; return { width: l * 6, actualBoundingBoxLeft: 0, actualBoundingBoxRight: l * 6, actualBoundingBoxAscent: 8, actualBoundingBoxDescent: 2 }; },
    fillText: function () {}, strokeText: function () {}, setLineDash: function () {}, getLineDash: function () { return []; },
  };
}

// ---------- jsdom window ----------
let dom;
try {
  dom = new JSDOM(fs.readFileSync(htmlPath, 'utf8'), {
    url: 'file://' + htmlPath,
    contentType: 'text/html',
    runScripts: 'outside-only',     // we run everything via vm against this window
    pretendToBeVisual: true,
    resources: undefined,            // no auto-fetch
  });
