const win = dom.window;
const ctx = dom.getInternalVMContext();
win.devicePixelRatio = 1;
win.innerWidth = 1280;
win.innerHeight = 720;

// ---------- canvas: 2d stub, webgl null (loop stubbed, GL unenforceable headless) ----------
win.HTMLCanvasElement.prototype.getContext = function (type) {
  if (type === '2d') return make2D(this);
  return null; // webgl / webgl2 -> null (matches no-GPU). three constructor takes it; render is stubbed.
};

// ---------- Image loader -> real PNG pixels from assets/textures ----------
const texCache = {};
(function () {
  try {
    fs.readdirSync(TEX_DIR).forEach(function (f) {
      if (/\.(png|jpg|jpeg|webp)$/i.test(f)) {
        try { texCache['assets/textures/' + f] = fs.readFileSync(path.join(TEX_DIR, f)); } catch (_) {}
