})();
let texLoaded = 0, texTotal = 0;
const ImgClass = function () {
  const self = this;
  this.width = 0; this.height = 0; this.naturalWidth = 0; this.naturalHeight = 0;
  this.complete = false; this.onload = null; this.onerror = null; this.decoding = 'auto';
  this.crossOrigin = null; this._data = null;
  Object.defineProperty(this, 'src', {
    get: function () { return self._src || ''; },
    set: function (v) {
      self._src = v; texTotal++;
      const base = String(v).replace(/^.*assets\//, 'assets/');
      const buf = texCache[base] || texCache[String(v)];
      setTimeout(function () {
        if (buf) {
          self.complete = true; self.naturalWidth = 256; self.naturalHeight = 256; self.width = 256; self.height = 256; self._data = buf;
          texLoaded++;
          if (typeof self.onload === 'function') self.onload();
        } else {
          texLoaded++;
          if (typeof self.onerror === 'function') self.onerror(new Error('img 404 ' + base));
        }
      }, 0);
    },
  });
};
win.Image = ImgClass;

// ---------- requestAnimationFrame pump (driven by harness) ----------
let rafQ = [];
let rafSeq = 0;
win.requestAnimationFrame = function (cb) { rafSeq++; rafQ.push(cb); return rafSeq; };
win.cancelAnimationFrame = function () {};

// ---------- virtual console -> jsdomError capture ----------
const consoleErrors = [];
const vc = new VirtualConsole();
vc.on('jsdomError', function (err) {
  consoleErrors.push({ kind: 'jsdomError', msg: err.message, stack: err.detail && err.detail.stack || err.stack || '' });
});
vc.on('error', function () { consoleErrors.push({ kind: 'console.error', msg: Array.prototype.slice.call(arguments).map(String).join(' ') }); });
