// ---------- crash reporting ----------
let firstError = null;
const renderStats = { count: 0 };
function recordError(src, e) {
  if (firstError) return;
  firstError = {
    src: src,
    msg: e && e.message ? e.message : String(e),
    stack: (e && e.stack) ? String(e.stack) : '',
    stage: (win.IS && win.IS._stages && win.IS._stages.length) ? win.IS._stages[win.IS._stages.length - 1] : null,
  };
}

// ---------- run a file in the jsdom window ----------
function runInWindow(file, label) {
  const src = fs.readFileSync(file, 'utf8');
  const fname = path.basename(file) || 'inline';
  try {
    vm.runInContext(src, ctx, { filename: fname });
  } catch (e) {
    recordError(fname, e);
  }
}

// ---------- phase 1: real three.min.js into jsdom window (global THREE) ----------
if (threeRel) runInWindow(path.join(ROOT, threeRel), threeRel);
const THREE_OK = !!(win.THREE && win.THREE.REVISION);

// ---------- phase 2: game scripts IN ORDER (skip three) ----------
gameScripts.forEach(function (s) { runInWindow(path.join(ROOT, s), s); });

// ---------- reflect boot diagnostics into harness ----------
const diagLines = [];
function wrapDiag() {
  try {
    const IS = win.IS;
    if (IS && typeof IS._diag === 'function') {
      const o = IS._diag;
      IS._diag = function (t) { diagLines.push('DIAG ' + t); try { return o(t); } catch (e) {} };
    }
  } catch (e) {}
  try {
    const o = win.__dbg;
    win.__dbg = function (t) { diagLines.push('DBG ' + t); try { return o(t); } catch (e) {} };
  } catch (e) {}
}

// ---------- stub renderer.render to count real frames ----------
(function patchRender() {
  try {
    if (win.THREE && win.THREE.WebGLRenderer && !win.THREE.WebGLRenderer.prototype.render.__harness) {
      win.THREE.WebGLRenderer.prototype.render = function () { renderStats.count++; };
      win.THREE.WebGLRenderer.prototype.render.__harness = true;
    }
  } catch (e) {}
})();

// ---------- phase 3: boot + pump ----------
function pump(frames, dt, done) {
  let i = 0;
  (function step() {
    const q = rafQ; rafQ = [];
    for (let k = 0; k < q.length; k++) {
      try { q[k](Date.now()); } catch (e) { recordError('raf', e); }
    }
    if (++i >= frames) return done();
    setTimeout(step, dt);
  })();
}

function report() {
  const IS = win.IS || {};
  const lines = [];
  lines.push('==== IRON SIEGE HARNESS REPORT ====');
  lines.push('THREE: ' + THREE_OK + (win.THREE ? ' r' + win.THREE.REVISION : '') + '  |  script order: ' + scripts.length + ' files');
  lines.push('_booted:    ' + IS._booted);
  lines.push('_loadStuck: ' + IS._loadStuck);
  lines.push('renders:    ' + renderStats.count);
  lines.push('img loaded: ' + texLoaded + '/' + texTotal);
  // stages
  const stages = IS._stages || [];
  lines.push('---- IS._stages (' + stages.length + ') ----');
  stages.slice(-40).forEach(function (s) { lines.push('  ' + s); });
  // diag/dbg
  lines.push('---- diag/dbg (' + diagLines.length + ') ----');
  diagLines.slice(-40).forEach(function (s) { lines.push('  ' + s); });
  // camera
  const cam = IS.camera || null;
  if (cam && cam.position) {
    const p = cam.position.toArray ? cam.position.toArray() : [cam.position.x, cam.position.y, cam.position.z];
    const zero = !p[0] && !p[1] && !p[2];
    lines.push('camera pos: [' + p.map(function (n) { return Number(n).toFixed(2); }).join(',') + '] ' + (zero ? '(ZERO!)' : '(moved)'));
  } else {
    lines.push('camera pos: (none on IS.camera)');
  }
  // errors
  lines.push('---- errors ----');
  if (firstError) {
    lines.push('FIRST UNCAUGHT [' + firstError.src + '] stage=' + firstError.stage);
    lines.push('  msg:  ' + firstError.msg);
    const sf = (firstError.stack || '').split('\n')[1] || '';
    lines.push('  frame1: ' + sf.trim());
  } else {
    lines.push('  (no uncaught error captured)');
  }
  consoleErrors.slice(0, 15).forEach(function (e) {
    lines.push('  [' + e.kind + '] ' + e.msg + (e.stack ? (' | f1 ' + ((e.stack).split('\n')[1] || '').trim()) : ''));
  });
  lines.push('TEXTURES: png present=' + Object.keys(texCache).length);
  process.stdout.write(lines.join('\n') + '\n');
  process.exit((firstError || !IS._booted || renderStats.count === 0) ? 2 : 0);
}

function startBoot() {
  wrapDiag();
  try {
    if (win.IS && typeof win.IS.boot === 'function') {
      win.IS.boot(win.document);
      diagLines.push('boot() returned');
    } else {
      diagLines.push('NO IS.boot');
      recordError('IS.boot', new Error('IS.boot is ' + typeof (win.IS && win.IS.boot)));
    }
  } catch (e) {
    recordError('IS.boot', e);
  }
}

// boot, then pump frames so loop + watchdog fire
startBoot();
const t0 = Date.now();
const LOOP_MS = 4000;   // pump ~250 frames
(function pumpLoop() {
  const q = rafQ; rafQ = [];
  for (let k = 0; k < q.length; k++) {
    try { q[k](Date.now()); } catch (e) { recordError('raf', e); }
  }
  if (Date.now() - t0 < LOOP_MS) setTimeout(pumpLoop, 16);
  else setTimeout(report, 50);
})();

# 开发用静态服务器（零依赖）。带正确 MIME，便于本地打开测试。
const http = require('http');
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const PORT = parseInt(process.env.PORT || '8080', 10);

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.htm': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.svg': 'image/svg+xml',
  '.wasm': 'application/wasm',
  '.ico': 'image/x-icon',
  '.glb': 'model/gltf-binary',
  '.gltf': 'model/gltf+json',
  '.map': 'application/json; charset=utf-8',
  '.txt': 'text/plain; charset=utf-8',
};

const server = http.createServer((req, res) => {
  let urlPath = decodeURIComponent((req.url || '/').split('?')[0]);
  if (urlPath === '/' || urlPath === '') urlPath = '/index.html';
  const filePath = path.join(ROOT, path.normalize(urlPath).replace(/^([/\\])+/, ''));

  // 防目录穿越
  if (!filePath.startsWith(ROOT)) {
    res.writeHead(403); res.end('403'); return;
  }

  fs.stat(filePath, (err, st) => {
    if (err || !st.isFile()) {
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('404 Not Found: ' + urlPath);
      return;
    }
    const ext = path.extname(filePath).toLowerCase();
    res.writeHead(200, {
      'Content-Type': MIME[ext] || 'application/octet-stream',
      'Content-Length': st.size,
      'Cache-Control': 'no-cache',
      'Access-Control-Allow-Origin': '*',
    });
    fs.createReadStream(filePath).pipe(res);
  });
});

server.listen(PORT, () => {
  console.log(`IRON SIEGE dev server -> http://localhost:${PORT}/`);
  console.log('root:', ROOT);
});

