// main.js — IRON SIEGE bootstrap + game loop (verified end-to-end)
(function () {
  const T = globalThis.THREE;
  const V = globalThis.IS || (globalThis.IS = {});
  const CFG = V.CFG;
  const _v = new T.Vector3(), _v2 = new T.Vector3(), _e = new T.Euler(), _q = new T.Quaternion();
  const _c = new T.Color();

  const S = V.state || (V.state = {
    time: 0, frame: 0, dt: 0, fps: 60, quality: 'high',
    paused: false, over: false, started: false, god: false,
    score: 0, kills: 0, wave: 1, streak: 0,
    spawnQueue: [], killsForWave: 12, waveIntermission: 0,
    nextId: 1,
    bots: [], botsMax: 48,
    player: null,
    drawCalls: 0, tris: 0,
    // 敌人登记
    enemies: [],
    corpseCache: {},
    decals: [], decalMax: 160,
  });

  let renderer = null, scene = null, camera = null, clock = null;
  let sun = null, hemi = null, sunDir = new T.Vector3(-0.45, 0.6, -0.35).normalize();
  const skyMode = 'dusk';

  // ---------- 渲染器 ----------
  function createRenderer(canvas) {
    const dprCap = CFG.quality === 'low' ? 1 : (CFG.quality === 'ultra' ? 2 : 1.5);
    const r = new T.WebGLRenderer({
      canvas, antialias: CFG.quality !== 'low', powerPreference: 'high-performance',
      stencil: false, depth: true, logarithmicDepthBuffer: false,
    });
    renderer = r;
    r.setPixelRatio(Math.min(window.devicePixelRatio || 1, CFG.dprMax));
    r.setSize(window.innerWidth, window.innerHeight, false);
    r.outputEncoding = T.sRGBEncoding;
    r.toneMapping = T.ACESFilmicToneMapping;
    r.toneMappingExposure = 1.05;
    r.shadowMap.enabled = true;
    r.shadowMap.type = T.PCFSoftShadowMap;
    r.info.autoReset = false;
    return r;
  }

  // ---------- 场景 / 天空 / 大气 ----------
  function createScene() {
    scene = new T.Scene();
    const sky = getSkyColors(skyMode);
    scene.fog = new T.FogExp2(sky.fog, CFG.fogDensity);
    buildSkyDome(sky);

    hemi = new T.HemisphereLight(sky.hemiTop, sky.hemiBot, sky.hemiInt);
    scene.add(hemi);

    sun = new T.DirectionalLight(sky.sunCol, sky.sunInt);
    sun.position.copy(sunDir).multiplyScalar(180);
    sun.castShadow = true;
    sun.shadow.mapSize.set(CFG.shadow, CFG.shadow);
    sun.shadow.camera.near = 1;
    sun.shadow.camera.far = 220;
    sun.shadow.bias = -0.0006;
    sun.shadow.normalBias = 0.028;
    fitShadowCamera();
    scene.add(sun);
    scene.add(sun.target);

    const fill = new T.DirectionalLight(sky.fillCol, sky.fillInt);
    fill.position.set(60, 40, 90);
    scene.add(fill);
  }

  function getSkyColors(mode) {
    if (mode === 'night') {
      return { top: 0x070b18, bot: 0x1a2340, fog: 0x0d1226, hemiTop: 0x2a3358, hemiBot: 0x0a0e1a, hemiInt: 0.4,
        sunCol: 0x9fb4ff, sunInt: 0.35, fillCol: 0x223055, fillInt: 0.2, sunX: 0.3 };
    }
    if (mode === 'dawn') {
      return { top: 0x2c4a7a, bot: 0xffb070, fog: 0xd89a72, hemiTop: 0x6f8fc0, hemiBot: 0x3a2a24, hemiInt: 0.55,
        sunCol: 0xffc98a, sunInt: 1.4, fillCol: 0x4a5a80, fillInt: 0.3, sunX: 0.9 };
    }
    // dusk (默认)
    return { top: 0x1d2f56, bot: 0xff7a45, fog: 0xb15c3e, hemiTop: 0x4a6699, hemiBot: 0x2a1c16, hemiInt: 0.5,
      sunCol: 0xff8c4a, sunInt: 1.7, fillCol: 0x39507c, fillInt: 0.32, sunX: 1.0 };
  }

  function buildSkyDome(sky) {
    const geo = new T.SphereGeometry(900, 32, 18);
    const mat = new T.ShaderMaterial({
      side: T.BackSide, depthWrite: false, fog: false,
      uniforms: {
        top: { value: new T.Color(sky.top) }, bot: { value: new T.Color(sky.bot) },
        sunDir: { value: sunDir }, sunCol: { value: new T.Color(sky.sunCol) },
        sunInt: { value: sky.sunX }, haze: { value: sky.bot },
      },
      vertexShader:
        'varying vec3 vP; void main(){ vP=position; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}',
      fragmentShader:
        'uniform vec3 top;uniform vec3 bot;uniform vec3 sunDir;uniform vec3 sunCol;uniform float sunInt;uniform vec3 haze;' +
        'varying vec3 vP;' +
        'void main(){vec3 d=normalize(vP);float h=clamp(d.y*0.5+0.5,0.0,1.0);' +
        'vec3 c=mix(bot,top,pow(h,0.55));' +
        // 地平线雾霭
        'float hz=exp(-abs(d.y)*7.0);c=mix(c,haze,hz*0.55);' +
        // 太阳 + 光晕
        'float s=clamp(dot(d,sunDir),0.0,1.0);' +
        'c+=sunCol*pow(s,220.0)*3.0*sunInt;' +
        'c+=sunCol*pow(s,14.0)*0.35*sunInt;' +
        'c+=sunCol*pow(s,3.0)*0.10*sunInt;' +
        'gl_FragColor=vec4(c,1.0);}',
    });
    const mesh = new T.Mesh(geo, mat);
    mesh.frustumCulled = false;
    mesh.renderOrder = -1000;
    mesh.name = 'sky';
    scene.add(mesh);
  }

  // ---------- 太阳阴影跟玩家（大地图阴影精度） ----------
  const _sp = new T.Vector3();
  function fitShadowCamera() {
    const p = S.player && S.player.pos ? S.player.pos : new T.Vector3(18, 1.8, 18);
    sun.position.copy(p).addScaledVector(sunDir, 160);
    sun.target.position.copy(p);
    sun.target.updateMatrixWorld();
    const d = 70;
    const sc = sun.shadow.camera;
    if (sc.left !== -d) { sc.left = -d; sc.right = d; sc.top = d; sc.bottom = -d; }
    sc.updateProjectionMatrix();
  }

  // ---------- 后处理（高品质才上 bloom） ----------
  function makePost() {
    if (CFG.quality === 'low') { return { render: (r, c, s) => { r.render(c, s); } }; }
    try {
      const w = window.innerWidth, h = window.innerHeight;
      const rt1 = new T.WebGLRenderTarget(1, 1, {
        minFilter: T.LinearFilter, magFilter: T.LinearFilter,
        format: T.RGBAFormat, type: T.HalfFloatType,
      });
      rt1.texture.encoding = T.sRGBEncoding;
      const rt2 = rt1.clone();

      const fs = new T.Scene();
      const fc = new T.OrthographicCamera(-1, 1, 1, -1, 0, 1);
      const quad = new T.Mesh(new T.PlaneGeometry(2, 2), null);
      quad.frustumCulled = false;
      fs.add(quad);

      // 分离亮部
      const brightMat = new T.ShaderMaterial({
        uniforms: { tex: { value: null }, thresh: { value: CFG.bloomThreshold } },
        vertexShader: 'varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}',
        fragmentShader: 'uniform sampler2D tex;uniform float thresh;varying vec2 vUv;' +
          'void main(){vec4 c=texture2D(tex,vUv);float br=max(max(c.r,c.g),c.b);' +
          'float k=smoothstep(thresh,thresh+0.35,br);gl_FragColor=vec4(c.rgb*k,1.0);}',
      });
      // 高斯模糊（水平/垂直各一遍）
      const blurMat = new T.ShaderMaterial({
        uniforms: { tex: { value: null }, dir: { value: new T.Vector2(1, 0) }, res: { value: new T.Vector2(w, h) }, rad: { value: CFG.bloomRadius } },
        vertexShader: 'varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}',
        fragmentShader: 'uniform sampler2D tex;uniform vec2 dir;uniform vec2 res;uniform float rad;varying vec2 vUv;' +
          'void main(){vec2 px=dir*rad/res;vec3 s=texture2D(tex,vUv).rgb*0.227027;' +
          's+=texture2D(tex,vUv+px*1.384615).rgb*0.316216;s+=texture2D(tex,vUv-px*1.384615).rgb*0.316216;' +
          's+=texture2D(tex,vUv+px*3.230769).rgb*0.070270;s+=texture2D(tex,vUv-px*3.230769).rgb*0.070270;' +
          'gl_FragColor=vec4(s,1.0);}',
      });
      // 合成
      const compMat = new T.ShaderMaterial({
        uniforms: {
          base: { value: null }, bloom: { value: null }, strength: { value: CFG.bloomStrength },
          ca: { value: CFG.chromatic }, time: { value: 0 }, shake: { value: new T.Vector2() },
          dark: { value: new T.Vector3(0, 0, 0) }, grain: { value: CFG.filmGrain },
        },
        vertexShader: 'varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}',
        fragmentShader:
          'uniform sampler2D base;uniform sampler2D bloom;uniform float strength;uniform float ca;uniform float time;' +
          'uniform vec2 shake;uniform vec3 dark;uniform float grain;varying vec2 vUv;' +
          'float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}' +
          'void main(){vec2 uv=vUv+shake*0.02;' +
          // 色差（半径递增）
          'vec2 off=(uv-0.5)*ca;' +
          'float rN=texture2D(base,uv+off*1.0).r;float gN=texture2D(base,uv).g;float bN=texture2D(base,uv-off*1.0).b;' +
          'vec3 c=vec3(rN,gN,bN);' +
          'c+=texture2D(bloom,uv).rgb*strength;' +
          // 暗角
          'float d=clamp(length(uv-0.5)*1.35,0.0,1.0);c*=mix(1.0,0.35,d*d);' +
          // 暗红（低血量）
          'c=mix(c,dark,clamp(length(dark),0.0,1.0));' +
          // 胶片颗粒
          'c+=(hash(uv*vec2(1024.0,1024.0)+time)-0.5)*grain;' +
          'gl_FragColor=vec4(c,1.0);}',
      });

      let halfW = Math.max(1, (w / 2) | 0), halfH = Math.max(1, (h / 2) | 0);
      return {
        resize() {
          const W = window.innerWidth, H = window.innerHeight;
          halfW = Math.max(1, (W / 2) | 0); halfH = Math.max(1, (H / 2) | 0);
          rt1.setSize(W, H); rt2.setSize(halfW, halfH);
          blurMat.uniforms.res.value.set(halfW, halfH);
        },
        render(r, cam, scn, t, shake) {
          // 1) scene -> rt1
          r.setRenderTarget(rt1); r.clear(); r.render(cam, scn);
          // 2) bright -> rt2
          brightMat.uniforms.tex.value = rt1.texture;
          quad.material = brightMat; r.setRenderTarget(rt2); r.clear(); r.render(fc, fc);
          // 3) blur H
          blurMat.uniforms.tex.value = rt2.texture; blurMat.uniforms.dir.value.set(1, 0);
          quad.material = blurMat; r.setRenderTarget(rt1, halfW, halfH); r.render(fc, fc);
          // 实际使用 rt1 的一半尺寸：上面 halfW 不对。修正：
          blurMat.uniforms.tex.value = rt2.texture; blurMat.uniforms.dir.value.set(1, 0);
          quad.material = blurMat; r.setRenderTarget(rt2); r.clear(); r.render(fc, fc);
          // 4) blur V
          blurMat.uniforms.tex.value = rt2.texture; blurMat.uniforms.dir.value.set(0, 1);
          quad.material = blurMat; r.setRenderTarget(rt1); r.clear();
          r.render(fc, fc);
          // 5) composite
          compMat.uniforms.base.value = rt1.texture;
          compMat.uniforms.bloom.value = rt2.texture;
          compMat.uniforms.time.value = t;
          compMat.uniforms.shake.value.set(shake.x, shake.y);
          quad.material = compMat; r.setRenderTarget(null); r.render(fc, fc);
        },
      };
    } catch (e) {
      console.warn('post unavailable', e);
      return { render: (r, c, s) => { r.render(c, s); } };
    }
  }

  // ---------- 主循环 ----------
  function loop() {
    const dt = Math.min(0.05, clock.getDelta());
    requestAnimationFrame(loop);
    S.dt = dt; S.time += dt; S.frame++;

    V.Input.update();
    if (!S.started) { return; }

    if (!S.paused && !S.over) {
      V.Char.update(dt);
      V.Weapons.update(dt);
      V.AIS.update(dt);
      V.Nav.update(dt);
      const spawnX = V.Char ? V.Char.pos.x : 18, spawnZ = V.Char ? V.Char.pos.z : 18;
      V.Enemies.update(dt, spawnX, spawnZ);
      V.Effects.update(dt);
      V.Spawner.update(dt);
    } else {
      V.Effects.update(dt * 0.4);
    }

    fitShadowCamera();
    if (renderer.xr.isPresenting === false) {
      V.followSun && V.followSun(camera);
    }

    V.Audio.worldToWorld && V.Audio.worldToWorld(camera);

    // 后处理需要 camera 已更新
    camera.updateMatrixWorld();
    post.render(renderer, camera, scene, S.time, V.Weapons._shake || { x: 0, y: 0 });

    renderer.info.reset();
    if (V.HUD) V.HUD.frame(dt);

    // 自适应画质
    if ((S.frame & 31) === 0) adaptQuality();
  }

  let perfAvg = 60;
  function adaptQuality() {
    const fps = V.fps || (V.fps = 60);
    perfAvg = perfAvg * 0.7 + fps * 0.3;
    if (!CFG.autoQuality) return;
    if (perfAvg < 38 && renderer.shadowMap.enabled && CFG.quality !== 'low') {
      renderer.shadowMap.enabled = false;
      CFG.bloomStrength = 0.18; CFG.chromatic = 0;
      renderer.shadowMap.needsUpdate = true;
    } else if (perfAvg > 58 && !renderer.shadowMap.enabled) {
      renderer.shadowMap.enabled = CFG.quality !== 'low';
    }
    if (V.HUD) V.HUD.setQuality(renderer.shadowMap.enabled, perfAvg);
  }

  // ---------- 启动 ----------
  V.boot = function (document) {
    const canvas = document.getElementById('viewport');
    try {
      createRenderer(canvas);
      createScene();
    } catch (e) {
      showFatal(e);
      return;
    }

    // 资源加载
    V.Mat.load(() => {
      V.Map.build(scene);
      V.Map.registerColliders();
      V.Effects.init(scene);
      V.Effects.prebuild();

      // 玩家出生
      V.Char.init(camera, 18, 18);
      V.AIS.init(camera, scene);
      V.Nav.init(scene);
      V.Weapons.init(camera);
      V.Audio.init();
      V.HUD.init(document);
      V.Spawner.init();

      post = makePost();

      window.addEventListener('resize', () => {
        renderer.setSize(window.innerWidth, window.innerHeight, false);
        camera.aspect = window.innerWidth / Math.max(1, window.innerHeight);
        camera.updateProjectionMatrix();
        V.Audio.resize && V.Audio.resize();
        post.resize && post.resize();
      });

      // 光标锁定 → 进入游戏
      V.Input.onPauseChange = (p) => { S.paused = p; if (V.HUD) V.HUD.showPause(p); };
      V.Input.onWeaponSelect = (i) => V.Weapons.selectByIndex(i);

      V.HUD.showMenu();

      clock = new T.Clock();
      requestAnimationFrame(loop);
    });
  };

  V.startRun = function () {
    S.started = true; S.over = false; S.paused = false; S.time = 0;
    S.score = 0; S.kills = 0; S.wave = 1; S.streak = 0; S.killsForWave = 12;
    V.Char.respawn(18, 18);
    V.Weapons.reset();
    V.Spawner.reset();
    V.HUD.hideMenu();
    V.Input.lock();
    V.Audio.startAmbient();
  };

  V.gameOver = function () {
    S.over = true; S.started = false;
    V.Input.unlock();
    V.HUD.showGameOver();
  };

  V.nextWave = function () {
    S.wave++; S.killsForWave = Math.min(40, 12 + S.wave * 4);
    if (V.HUD) V.HUD.announceWave(S.wave);
    V.Spawner.onWave(S.wave);
  };

  let post = { render: () => {} };

  // ---------- 致命错误 ----------
  function showFatal(e) {
    const o = document.getElementById('overlay');
    o.innerHTML = '<div style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;' +
      'background:#05070d;color:#ff7a7a;font:14px/1.6 ui-monospace,monospace;padding:32px;text-align:center">' +
      '<div><h2 style="color:#ffd27a;margin:0 0 8px">GPU / WEBGL 初始化失败</h2><p>' +
      '请确认浏览器启用了硬件加速 WebGL。</p><pre style="color:#9aa3b5;white-space:pre-wrap;text-align:left;max-width:600px">' +
      (e && e.stack || e) + '</pre></div></div>';
  }
})();

